+import { NextRequest, NextResponse } from 'next/server';
+import { isAdminRequest } from '@/lib/adminSession';
+import { listDeliveries } from '@/lib/mail/store';
+
+export const runtime = 'nodejs';
+
+function unauthorizedResponse() {
+  return NextResponse.json(
+    { error: '관리자 인증이 만료되었습니다. 다시 로그인해 주세요.', code: 'UNAUTHORIZED' },
+    { status: 401 },
+  );
+}
+
+/** 발송 기록, 최신순. 관리자가 "무엇이 건물 밖으로 나갔는지" 를 본다. 본문은 없다. */
+export async function GET(request: NextRequest) {
+  if (!isAdminRequest(request)) return unauthorizedResponse();
+
+  try {
+    const { searchParams } = request.nextUrl;
+    const limit = Number(searchParams.get('limit'));
+    const status = searchParams.get('status') ?? undefined;
+    const page = await listDeliveries({ status, limit: Number.isFinite(limit) ? limit : undefined });
+    return NextResponse.json(page, { headers: { 'Cache-Control': 'no-store' } });
+  } catch (error) {
+    console.error('GET /api/mail/deliveries failed:', error);
+    return NextResponse.json({ error: '발송 기록을 읽지 못했습니다.' }, { status: 500 });
+  }
+}
