@@ -0,0 +1,46 @@
+import { NextRequest, NextResponse } from 'next/server';
+import { readActivityData } from '@/lib/activityData';
+import { isAdminRequest } from '@/lib/adminSession';
+import { isEmailAddress } from '@/lib/mail/config';
+import { getMailService, MailUnavailableError, testNotification } from '@/lib/mail/service';
+
+export const runtime = 'nodejs';
+
+function unauthorizedResponse() {
+  return NextResponse.json(
+    { error: '관리자 인증이 만료되었습니다. 다시 로그인해 주세요.', code: 'UNAUTHORIZED' },
+    { status: 401 },
+  );
+}
+
+/**
+ * 시험 발송. 저장된 설정으로 실제 한 통을 바로 보내고 결과를 그 자리에서 돌려준다 —
+ * 릴레이 설정은 한 번에 맞는 일이 드물다. 이것만은 요청이 발송을 기다린다.
+ */
+export async function POST(request: NextRequest) {
+  if (!isAdminRequest(request)) return unauthorizedResponse();
+
+  try {
+    const body: unknown = await request.json();
+    const recipient = typeof body === 'object' && body !== null && typeof (body as { recipient?: unknown }).recipient === 'string'
+      ? (body as { recipient: string }).recipient.trim()
+      : '';
+    if (!isEmailAddress(recipient)) {
+      return NextResponse.json({ error: '받는 사람은 이름@호스트 모양이어야 합니다.', code: 'INVALID_RECIPIENT' }, { status: 400 });
+    }
+
+    const { dashboardTitle } = await readActivityData();
+    const delivery = await getMailService().sendNow(testNotification(dashboardTitle), recipient);
+    return NextResponse.json({ sent: true, recipient, delivery });
+  } catch (error) {
+    if (error instanceof SyntaxError) {
+      return NextResponse.json({ error: '요청 JSON 문법이 올바르지 않습니다.' }, { status: 400 });
+    }
+    if (error instanceof MailUnavailableError) {
+      return NextResponse.json({ error: error.message, code: 'MAIL_UNAVAILABLE' }, { status: 409 });
+    }
+    // 릴레이 오류는 관리자가 고칠 정보다. 그대로 보여 준다(비밀번호는 담기지 않는다).
+    const message = error instanceof Error ? error.message : '알 수 없는 오류';
+    return NextResponse.json({ error: `발송에 실패했습니다: ${message}`, code: 'MAIL_SEND_FAILED' }, { status: 502 });
+  }
+}
