+/**
+ * 방문 추적 설정 카드. 설정은 서버의 data/tracking.json 에 저장되고, 화면에서 바꾸면
+ * 다음 페이지부터 바로 반영된다. 아래에는 브라우저가 정책 때문에 막은 출처가 보이고,
+ * 한 번 눌러 허용 목록에 넣을 수 있다.
+ */
+export default function TrackingSettings({ onUnauthorized }: Props) {
+  const [config, setConfig] = useState<TrackingConfig>(defaultTrackingConfig);
+  const [sources, setSources] = useState<PolicySources>({ scripts: [], connects: [], images: [] });
+  const [violations, setViolations] = useState<CspViolation[]>([]);
+  const [isLoaded, setIsLoaded] = useState(false);
+  const [isSaving, setIsSaving] = useState(false);
+  const [isDirty, setIsDirty] = useState(false);
+  const [feedback, setFeedback] = useState<Feedback | null>(null);
+
