diff --git a/components/TrackingSnippet.tsx b/components/TrackingSnippet.tsx
new file mode 100644
index 0000000..cb31992
--- /dev/null
+++ b/components/TrackingSnippet.tsx
@@ -0,0 +1,39 @@
+import type { SnippetScript } from '@/lib/tracking/core';
+
+const ATTRIBUTE_PROP_NAMES: Record<string, string> = {
+  crossorigin: 'crossOrigin',
+  referrerpolicy: 'referrerPolicy',
+  nomodule: 'noModule',
+  charset: 'charSet',
+  fetchpriority: 'fetchPriority',
+};
+
+/**
+ * 추적 스니펫의 <script> 들을 요청 nonce 와 함께 그린다. 문자열을 그대로 심지 않고
+ * 요소로 그리므로 속성값은 React 가 이스케이프하고, 모든 태그가 빠짐없이 nonce 를 단다.
+ */
+export default function TrackingSnippet({ scripts, nonce }: { scripts: SnippetScript[]; nonce: string }) {
+  return (
+    <>
+      {scripts.map((script, index) => {
+        const props: Record<string, string | boolean> = { nonce };
+        for (const [name, value] of Object.entries(script.attributes)) {
+          props[ATTRIBUTE_PROP_NAMES[name] ?? name] = value;
+        }
+        if (script.src) {
+          // 붙여 넣은 스니펫이 동기 로더일 수 있다. 관리자가 적은 그대로 두어야 도구가 동작한다.
+          // eslint-disable-next-line @next/next/no-sync-scripts
+          return <script key={index} {...props} src={script.src} data-tracking-snippet="" />;
+        }
+        return (
+          <script
+            key={index}
+            {...props}
+            data-tracking-snippet=""
+            dangerouslySetInnerHTML={{ __html: script.inline ?? '' }}
+          />
+        );
+      })}
+    </>
+  );
+}
