+import fs from 'node:fs/promises';
+import path from 'node:path';
+import { expect, test, type APIRequestContext } from '@playwright/test';
+import { startFakeRelay, unusedPort, type FakeRelay } from '../lib/mail/testing';
+
+const adminPassword = 'e2e-admin-password';
+const mailConfigPath = path.join(process.cwd(), 'test-results', 'e2e-data', 'mail.json');
+
+interface Activity {
+  id: string;
+  parentId: string | null;
+  level: number;
+  time: string;
+  title: string;
+  status: string;
+}
+
+interface Delivery {
+  event: string;
+  recipient: string;
+  subject: string;
+  status: string;
+  attempts: number;
+  error_message: string;
+}
+
+async function loginAsAdmin(request: APIRequestContext) {
+  const response = await request.post('/api/auth/login', { data: { pw: adminPassword, role: 'admin' } });
+  expect(response.ok()).toBeTruthy();
+}
+
+async function activities(request: APIRequestContext): Promise<Activity[]> {
+  return (await (await request.get('/api/activities')).json()).activities;
+}
+
+/** 액티비티 하나의 상태를 바꾸는 저장. 응답에 걸린 시간을 함께 돌려준다 — 메일이 요청을 막지 않는지 본다. */
+async function setStatus(request: APIRequestContext, id: string, status: string) {
+  const current = await activities(request);
+  const started = Date.now();
+  const response = await request.put('/api/activities', {
+    data: { activities: current.map((activity) => (activity.id === id ? { ...activity, status } : activity)), targetId: id, newStatus: status },
+  });
+  expect(response.status(), await response.text()).toBe(200);
+  return Date.now() - started;
+}
+
+async function deliveries(request: APIRequestContext): Promise<{ items: Delivery[]; summary: { total: number } }> {
+  const response = await request.get('/api/mail/deliveries?limit=50');
+  expect(response.status()).toBe(200);
+  return response.json();
+}
+
+async function waitForDeliveries(request: APIRequestContext, predicate: (items: Delivery[]) => boolean, timeoutMs = 15_000) {
+  const deadline = Date.now() + timeoutMs;
+  let page = await deliveries(request);
+  while (!predicate(page.items) && Date.now() < deadline) {
+    await new Promise((resolve) => setTimeout(resolve, 250));
+    page = await deliveries(request);
+  }
+  return page;
+}
+
+function decodeSubject(raw: string) {
+  const line = raw.split('\r\n\r\n')[0].split('\r\n').join('\n').replace(/\n /g, '').split('\n').find((header) => header.startsWith('Subject: ')) ?? '';
+  return line.slice('Subject: '.length).replace(/=\?UTF-8\?B\?([^?]+)\?=/g, (_match, encoded: string) => Buffer.from(encoded, 'base64').toString('utf-8'));
+}
+
+let relay: FakeRelay;
+let original: Activity[];
+
+test.beforeAll(async ({ request }) => {
+  relay = await startFakeRelay({ auth: { username: 'mailer', password: 's3cret' } });
+  original = await activities(request);
+});
