+interface CollectorHit {
+  method: string;
+  path: string;
+  body: string;
+  headers: http.IncomingHttpHeaders;
+}
+
+let collector: http.Server;
+let collectorUrl: string;
+const hits: CollectorHit[] = [];
+
+test.beforeAll(async () => {
+  collector = http.createServer((request, response) => {
+    let body = '';
+    request.on('data', (chunk) => { body += chunk; });
+    request.on('end', () => {
+      hits.push({ method: request.method ?? '', path: request.url ?? '', body, headers: request.headers });
+      if (request.url === '/tracker.js') {
+        response.writeHead(200, { 'Content-Type': 'application/javascript' });
+        response.end(`(function(){var s=document.currentScript;var e=s.getAttribute('data-endpoint');
+          window.__momentoLoaded=true;
+          fetch(e+'/collect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({site:s.getAttribute('data-site-id'),page:location.pathname})});
+        })();`);
+        return;
+      }
+      response.writeHead(204);
+      response.end();
+    });
+  });
+  await new Promise<void>((resolve) => collector.listen(0, '127.0.0.1', resolve));
+  collectorUrl = `http://127.0.0.1:${(collector.address() as AddressInfo).port}`;
+});
+
+test.afterAll(async () => {
+  await new Promise<void>((resolve) => collector.close(() => resolve()));
+});
+
+function scriptDirective(policy: string) {
+  return policy.split(';').map((part) => part.trim()).find((part) => part.startsWith('script-src ')) ?? '';
+}
+
+function nonceOf(policy: string) {
+  return scriptDirective(policy).match(/'nonce-([^']+)'/)?.[1] ?? '';
+}
+
+function snippetTags(html: string) {
+  return [...html.matchAll(/<script[^>]*data-tracking-snippet[^>]*>/g)].map((match) => match[0]);
+}
+
+async function loginAsAdmin(request: APIRequestContext) {
+  const response = await request.post('/api/auth/login', { data: { pw: adminPassword, role: 'admin' } });
+  expect(response.ok()).toBeTruthy();
+}
+
+async function saveTracking(request: APIRequestContext, config: Record<string, unknown>) {
+  const response = await request.put('/api/tracking', { data: config });
+  expect(response.status(), await response.text()).toBe(200);
+  return response.json();
+}
+
+function cspErrors(page: Page) {
+  const errors: string[] = [];
+  page.on('console', (message) => {
+    if (message.type() === 'error' && /Content Security Policy/i.test(message.text())) errors.push(message.text());
+  });
+  return errors;
+}
