@@ -0,0 +1,140 @@
+import assert from 'node:assert/strict';
+import { describe, it } from 'node:test';
+import type { Activity } from '../types.ts';
+import { defaultMailConfig, type MailConfig } from './config.ts';
+import { testNotification } from './events.ts';
+import { createMailService, MailUnavailableError, notifyActivityChanges, smtpOptionsFrom } from './service.ts';
+import type { Delivery } from './store.ts';
+import type { SmtpEnvelope } from './smtp.ts';
+
+function ready(overrides: Partial<MailConfig> = {}): MailConfig {
+  return {
+    ...defaultMailConfig(),
+    enabled: true,
+    smtp_host: 'relay.corp.example',
+    from_address: 'cutover@corp.example',
+    recipients: 'a@corp.example, b@corp.example',
+    ...overrides,
+  };
+}
+
+/** 기록과 전송을 메모리에서 흉내 낸다. */
+function harness(config: MailConfig, send?: (envelope: SmtpEnvelope) => Promise<void>) {
+  const deliveries: Delivery[] = [];
+  const sent: SmtpEnvelope[] = [];
+  const service = createMailService({
+    readConfig: async () => config,
+    send: async (_options, envelope) => {
+      sent.push(envelope);
+      if (send) await send(envelope);
+    },
+    record: async (delivery) => { deliveries.push({ ...delivery }); },
+    update: async (id, patch) => {
+      const index = deliveries.findIndex((delivery) => delivery.id === id);
+      deliveries[index] = { ...deliveries[index], ...patch };
+    },
+    sleep: async () => undefined,
+  });
+  return { service, deliveries, sent };
+}
+
+const activities = (status: Activity['status']): Activity[] => [
+  { id: '1', parentId: null, level: 1, time: '21:00', title: '[Task#1] 서비스 중지', status },
+];
+
+describe('알림 발송', () => {
+  it('꺼져 있으면 보내지도 기록하지도 않는다', async () => {
+    const { service, deliveries, sent } = harness(defaultMailConfig());
+    await service.notify(testNotification('훈련'));
+    assert.equal(sent.length, 0);
+    assert.equal(deliveries.length, 0);
+  });
+
+  it('명부의 모두에게 한 통씩 보내고 성공을 기록한다', async () => {
+    const { service, deliveries, sent } = harness(ready());
+    await service.notify(testNotification('훈련'));
+    assert.deepEqual(sent.map((envelope) => envelope.to), ['a@corp.example', 'b@corp.example']);
+    assert.deepEqual(deliveries.map((delivery) => [delivery.recipient, delivery.status, delivery.attempts]), [
+      ['a@corp.example', 'sent', 1],
+      ['b@corp.example', 'sent', 1],
+    ]);
+    assert.equal(deliveries[0].subject, '[훈련] SMTP 발송 테스트');
+    // 기록에 본문은 없다.
+    assert.equal('body' in deliveries[0], false);
+    assert.equal(JSON.stringify(deliveries).includes('테스트 메일입니다'), false);
+  });
+
+  it('릴레이가 죽어 있으면 한 번 더 시도한 뒤 실패로 기록하고 던지지 않는다', async () => {
+    const { service, deliveries, sent } = harness(ready(), async () => { throw new Error('SMTP 연결 실패 (relay:25): ECONNREFUSED'); });
+    await service.notify(testNotification('훈련'));
+    assert.equal(sent.length, 4);
+    assert.deepEqual(deliveries.map((delivery) => [delivery.status, delivery.attempts]), [['failed', 2], ['failed', 2]]);
+    assert.match(deliveries[0].error_message, /ECONNREFUSED/);
+  });
+
+  it('켜져 있지만 설정이 모자라면 보내지 않고 이유를 남긴다', async () => {
+    const { service, deliveries, sent } = harness(ready({ smtp_host: '' }));
+    await service.notify(testNotification('훈련'));
+    assert.equal(sent.length, 0);
+    assert.equal(deliveries.length, 1);
+    assert.equal(deliveries[0].status, 'failed');
+    assert.match(deliveries[0].error_message, /mail\.smtp_host/);
+
+    const empty = harness(ready({ recipients: '' }));
+    await empty.service.notify(testNotification('훈련'));
+    assert.match(empty.deliveries[0].error_message, /mail\.recipients/);
+  });
+});
+
+describe('시험 발송', () => {
+  it('바로 보내고 결과를 돌려주며 실패는 던진다', async () => {
+    const ok = harness(ready());
+    const delivery = await ok.service.sendNow(testNotification('훈련'), 'me@corp.example');
+    assert.equal(delivery.status, 'sent');
+    assert.equal(ok.sent[0].to, 'me@corp.example');
+
+    const broken = harness(ready(), async () => { throw new Error('RCPT TO 실패: 550 No such user'); });
+    await assert.rejects(broken.service.sendNow(testNotification('훈련'), 'me@corp.example'), /550/);
+    assert.equal(broken.deliveries[0].status, 'failed');
+    assert.equal(broken.sent.length, 1, '시험 발송은 재시도하지 않는다');
+
+    const off = harness(defaultMailConfig());
+    await assert.rejects(off.service.sendNow(testNotification('훈련'), 'me@corp.example'), MailUnavailableError);
+  });
+});
+
+describe('상황판 변경 → 메일', () => {
+  it('지연으로 바뀌면 한 통이 나가고, 스위치를 끄면 그 종류만 멎는다', async () => {
+    const on = harness(ready({ recipients: 'ops@corp.example' }));
+    await notifyActivityChanges(activities('진행'), activities('지연'), '훈련', on.service);
+    assert.equal(on.deliveries.length, 1);
+    assert.equal(on.deliveries[0].event, 'activity.delayed');
+    assert.equal(on.deliveries[0].subject, '[훈련] 지연: [Task#1] 서비스 중지');
+
+    const off = harness(ready({ recipients: 'ops@corp.example', notify_activity_delayed: false }));
+    await notifyActivityChanges(activities('진행'), activities('지연'), '훈련', off.service);
+    assert.equal(off.deliveries.length, 0);
+  });
+
+  it('메일감이 없으면 설정조차 읽지 않는다', async () => {
+    let reads = 0;
+    const service = createMailService({ readConfig: async () => { reads += 1; return ready(); } });
+    await notifyActivityChanges(activities('대기'), activities('진행'), '훈련', service);
+    assert.equal(reads, 0);
+  });
+
+  it('설정을 읽다 실패해도 던지지 않는다', async () => {
+    const service = createMailService({ readConfig: async () => { throw new Error('disk'); } });
+    await notifyActivityChanges(activities('진행'), activities('지연'), '훈련', service);
+  });
+});
+
+describe('릴레이 옵션', () => {
+  it('465 포트에 auto 면 처음부터 TLS 로 붙고, EHLO 이름은 보내는 주소의 도메인이다', () => {
+    const options = smtpOptionsFrom(ready({ smtp_port: 465 }));
+    assert.equal(options.security, 'tls');
+    assert.equal(options.heloName, 'corp.example');
+    assert.equal(smtpOptionsFrom(ready()).security, 'auto');
+    assert.equal(smtpOptionsFrom(ready()).timeoutMs, 10_000);
+  });
+});
