@@ -0,0 +1,233 @@
+/**
+ * 발송 서비스. 설정을 읽고, 받는 사람을 정하고, 시도마다 기록하고, 릴레이로 보낸다.
+ *
+ * 요청 경로에서는 notify 를 Next 의 after() 안에서 부른다 — 응답이 나간 뒤에 돌므로 릴레이가
+ * 느리거나 죽어 있어도 상태 클릭 하나가 기다리지 않는다. 발송 실패는 그 요청의 실패가 아니다.
+ * 전송 함수와 기록 함수는 바꿔 끼울 수 있어 테스트가 실제 릴레이 없이 돈다.
+ */
+import { randomUUID } from 'node:crypto';
+import type { Activity } from '../types.ts';
+import {
+  mailUnavailableReason,
+  parseRecipients,
+  type MailConfig,
+} from './config.ts';
+import {
+  composeNotification,
+  detectMailChanges,
+  renderBody,
+  testNotification,
+  type Notification,
+} from './events.ts';
+import { composeMessage } from './message.ts';
+import { readMailConfig, recordDelivery, updateDelivery, type Delivery } from './store.ts';
+import { sendMail, type SmtpEnvelope, type SmtpOptions } from './smtp.ts';
+
+export interface MailServiceDeps {
+  readConfig: () => Promise<MailConfig>;
+  send: (options: SmtpOptions, envelope: SmtpEnvelope) => Promise<void>;
+  record: (delivery: Delivery) => Promise<void>;
+  update: (id: string, patch: Partial<Pick<Delivery, 'status' | 'attempts' | 'error_message'>>) => Promise<void>;
+  now: () => Date;
+  sleep: (ms: number) => Promise<void>;
+}
+
+export class MailUnavailableError extends Error {
+  constructor(message: string) {
+    super(message);
+    this.name = 'MailUnavailableError';
+  }
+}
+
+const RETRY_DELAY_MS = 2000;
+const MAX_ERROR_LENGTH = 1000;
+
+export function smtpOptionsFrom(config: MailConfig): SmtpOptions {
+  const domain = config.from_address.split('@')[1] ?? '';
+  return {
+    host: config.smtp_host,
+    port: config.smtp_port,
+    // 465 는 처음부터 TLS 인 포트다. auto 인 채로 두면 평문 인사를 기다리다 시간 초과가 난다.
+    security: config.security === 'auto' && config.smtp_port === 465 ? 'tls' : config.security,
+    skipTlsVerify: config.skip_tls_verify,
+    username: config.username,
+    password: config.password,
+    timeoutMs: config.timeout_seconds * 1000,
+    heloName: domain || 'localhost',
+  };
+}
+
+function errorText(error: unknown) {
+  const text = error instanceof Error ? error.message : String(error);
+  return text.length > MAX_ERROR_LENGTH ? text.slice(0, MAX_ERROR_LENGTH) : text;
+}
+
+export function createMailService(overrides: Partial<MailServiceDeps> = {}) {
+  const deps: MailServiceDeps = {
+    readConfig: readMailConfig,
+    send: sendMail,
+    record: recordDelivery,
+    update: updateDelivery,
+    now: () => new Date(),
+    sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
+    ...overrides,
+  };
+
+  function newDelivery(notification: Notification, recipient: string): Delivery {
+    const moment = deps.now().toISOString();
+    return {
+      id: randomUUID(),
+      event: notification.event,
+      recipient,
+      subject: notification.subject.slice(0, 300),
+      status: 'queued',
+      attempts: 0,
+      error_message: '',
+      created_at: moment,
+      updated_at: moment,
+    };
+  }
+
+  async function complete(delivery: Delivery, attempts: number, cause: unknown) {
+    const patch = cause === undefined
+      ? { status: 'sent' as const, attempts, error_message: '' }
+      : { status: 'failed' as const, attempts, error_message: errorText(cause) };
+    if (cause !== undefined) {
+      // 비밀번호는 오류 문장에 들어가지 않는다(smtp.ts). 여기서도 설정을 통째로 찍지 않는다.
+      console.warn(`메일 발송 실패 [${delivery.event}] → ${delivery.recipient}: ${patch.error_message}`);
+    }
+    await deps.update(delivery.id, patch).catch((error) => console.warn('메일 발송 기록을 갱신하지 못했습니다:', error));
+  }
+
+  /** 한 번 더 시도한다. 잠깐 연결을 거부하는 릴레이는 흔하고, 알림을 잃는 것이 2초 기다리는 것보다 나쁘다. */
+  async function deliver(config: MailConfig, delivery: Delivery, envelope: SmtpEnvelope, retries: number) {
+    let cause: unknown;
+    let attempts = 0;
+    for (attempts = 1; attempts <= retries + 1; attempts += 1) {
+      try {
+        await deps.send(smtpOptionsFrom(config), envelope);
+        cause = undefined;
+        break;
+      } catch (error) {
+        cause = error ?? new Error('알 수 없는 오류');
+        if (attempts <= retries) await deps.sleep(RETRY_DELAY_MS);
+      }
+    }
+    await complete(delivery, Math.min(attempts, retries + 1), cause);
+    return cause;
+  }
+
+  function envelopeFor(config: MailConfig, notification: Notification, recipient: string): SmtpEnvelope {
+    return {
+      from: config.from_address,
+      to: recipient,
+      data: composeMessage({
+        from: { name: config.from_name, address: config.from_address },
+        to: recipient,
+        subject: notification.subject,
+        body: renderBody(notification, config),
+      }, deps.now()),
+    };
+  }
+
+  /** 켜져 있지만 보낼 수 없을 때, 기록에 이유를 남긴다. 조용히 넘기면 "안 왔다" 에 답할 수 없다. */
+  async function recordUnavailable(notification: Notification, reason: string) {
+    const delivery = { ...newDelivery(notification, '-'), status: 'failed' as const, error_message: reason };
+    await deps.record(delivery).catch((error) => console.warn('메일 발송 기록을 남기지 못했습니다:', error));
+  }
+
+  return {
+    config: () => deps.readConfig(),
+
+    /**
+     * 명부의 모두에게 한 통씩 보낸다. 절대 던지지 않는다 — 호출한 요청은 이미 끝났다.
+     * 꺼져 있으면 아무 기록도 남기지 않는다(새로 설치한 곳은 달라지지 않는다).
+     */
+    async notify(notification: Notification): Promise<void> {
+      let config: MailConfig;
+      try {
+        config = await deps.readConfig();
+      } catch (error) {
+        console.warn('메일 설정을 읽지 못해 알림을 보내지 않습니다:', error);
+        return;
+      }
+      if (!config.enabled) return;
+
+      const reason = mailUnavailableReason(config);
+      if (reason) {
+        await recordUnavailable(notification, reason);
+        return;
+      }
+      const recipients = parseRecipients(config.recipients);
+      if (recipients.length === 0) {
+        await recordUnavailable(notification, '받는 사람(mail.recipients)이 비어 있습니다.');
+        return;
+      }
+
+      for (const recipient of recipients) {
+        const delivery = newDelivery(notification, recipient);
+        try {
+          await deps.record(delivery);
+          await deliver(config, delivery, envelopeFor(config, notification, recipient), 1);
+        } catch (error) {
+          console.warn('메일 발송 기록을 남기지 못했습니다:', error);
+        }
+      }
+    },
+
+    /**
+     * 시험 발송. 바로 보내고 결과를 돌려준다 — 관리 화면의 단추가 그 자리에서 답을 보여 준다.
+     * 재시도하지 않는다(사람이 보고 있다).
+     */
+    async sendNow(notification: Notification, recipient: string): Promise<Delivery> {
+      const config = await deps.readConfig();
+      const reason = mailUnavailableReason(config);
+      if (reason) throw new MailUnavailableError(reason);
+
+      const delivery = newDelivery(notification, recipient);
+      await deps.record(delivery);
+      const cause = await deliver(config, delivery, envelopeFor(config, notification, recipient), 0);
+      if (cause !== undefined) {
+        throw cause instanceof Error ? cause : new Error(errorText(cause));
+      }
+      return { ...delivery, status: 'sent', attempts: 1, updated_at: deps.now().toISOString() };
+    },
+  };
+}
+
+export type MailService = ReturnType<typeof createMailService>;
+
+const SERVICE_KEY = '__cutoverMailService';
+
+/** 라우트마다 모듈이 따로 묶여도 하나의 서비스를 쓴다. */
+export function getMailService(): MailService {
+  const store = globalThis as typeof globalThis & { [SERVICE_KEY]?: MailService };
+  if (!store[SERVICE_KEY]) store[SERVICE_KEY] = createMailService();
+  return store[SERVICE_KEY];
+}
+
+/**
+ * 상황판 저장 뒤에 부른다. 저장 전후를 비교해 메일감을 고르고, 있으면 한 통으로 묶어 보낸다.
+ * after() 안에서 돌도록 만들어졌으므로 무엇도 던지지 않는다.
+ */
+export async function notifyActivityChanges(
+  before: Activity[],
+  after: Activity[],
+  dashboardTitle: string,
+  service: MailService = getMailService(),
+): Promise<void> {
+  try {
+    const changes = detectMailChanges(before, after);
+    if (changes.length === 0) return;
+    // 스위치는 설정을 읽어야 알 수 있다. 꺼져 있으면 여기서 읽는 것이 유일한 비용이다.
+    const config = await service.config();
+    if (!config.enabled) return;
+    const notification = composeNotification(changes, config, dashboardTitle);
+    if (!notification) return;
+    await service.notify(notification);
+  } catch (error) {
+    console.warn('메일 알림 처리 중 오류가 났지만 상황판 저장에는 영향이 없습니다:', error);
+  }
+}
+
+export { testNotification };
