+/**
+ * 최소한의 SMTP 클라이언트. 사내 릴레이(포트 25 · 인증 없음 · TLS 없음)가 기본이고,
+ * 서버가 알리는 만큼만 STARTTLS 와 인증을 올린다 — 그래서 인증 없는 사내 릴레이와 둘 다
+ * 요구하는 외부 서비스가 같은 설정 항목으로 동작한다.
+ *
+ * 의존성을 더하지 않고 node:net / node:tls 로 쓴다. 보내는 쪽 로직은 짧고, 폐쇄망
+ * 이미지에 들어가는 것이 하나 늘지 않는다.
+ */
+import net from 'node:net';
+import tls from 'node:tls';
+import type { MailSecurity } from './config.ts';
+
+export interface SmtpOptions {
+  host: string;
+  port: number;
+  security: MailSecurity;
+  skipTlsVerify: boolean;
+  username: string;
+  password: string;
+  timeoutMs: number;
+  /** EHLO 이름. 보내는 주소의 도메인을 쓰면 인사말을 검사하는 릴레이가 덜 까다롭다. */
+  heloName: string;
+}
+
+export interface SmtpEnvelope {
+  from: string;
+  to: string;
+  /** composeMessage 가 만든 완성된 메시지(헤더 + 본문). */
+  data: string;
+}
+
+interface SmtpReply {
+  code: number;
+  lines: string[];
+}
+
+export class SmtpError extends Error {
+  constructor(message: string) {
+    super(message);
+    this.name = 'SmtpError';
+  }
+}
+
+type Waiter = { resolve: (reply: SmtpReply) => void; reject: (error: Error) => void };
+
+class SmtpConnection {
+  private socket: net.Socket;
+  private buffer = '';
+  private pending: string[] = [];
+  private waiter: Waiter | null = null;
+  private closed: Error | null = null;
+  private options: SmtpOptions;
+
+  constructor(socket: net.Socket, options: SmtpOptions) {
+    this.socket = socket;
+    this.options = options;
+    this.attach(socket);
+  }
+
+  private attach(socket: net.Socket) {
+    this.socket = socket;
+    socket.setEncoding('utf-8');
+    socket.setTimeout(this.options.timeoutMs);
+    socket.on('data', (chunk: string) => this.onData(chunk));
+    socket.on('timeout', () => this.fail(new SmtpError(`SMTP 응답 시간 초과 (${this.options.timeoutMs}ms)`)));
+    socket.on('error', (error: Error) => this.fail(new SmtpError(`SMTP 연결 오류: ${error.message}`)));
+    socket.on('close', () => this.fail(new SmtpError('SMTP 연결이 끊어졌습니다.')));
+  }
+
+  private fail(error: Error) {
+    if (!this.closed) this.closed = error;
+    const waiter = this.waiter;
+    this.waiter = null;
+    waiter?.reject(error);
+  }
+
+  private onData(chunk: string) {
+    this.buffer += chunk;
+    let index = this.buffer.indexOf('\r\n');
+    const lines: string[] = [];
+    while (index !== -1) {
+      lines.push(this.buffer.slice(0, index));
+      this.buffer = this.buffer.slice(index + 2);
+      index = this.buffer.indexOf('\r\n');
+    }
+    if (lines.length === 0) return;
+    this.pending.push(...lines);
+    this.flush();
+  }
+
+  /** 마지막 줄은 `250 ` 처럼 코드 뒤에 공백이 오고, 이어지는 줄은 `250-` 다. */
+  private flush() {
+    if (!this.waiter) return;
+    const end = this.pending.findIndex((line) => /^\d{3}(?: |$)/.test(line));
+    if (end === -1) return;
+    const lines = this.pending.splice(0, end + 1);
+    const code = Number(lines[lines.length - 1].slice(0, 3));
+    const waiter = this.waiter;
+    this.waiter = null;
+    waiter.resolve({ code, lines: lines.map((line) => line.slice(4)) });
+  }
+
+  read(): Promise<SmtpReply> {
+    if (this.closed) return Promise.reject(this.closed);
+    return new Promise<SmtpReply>((resolve, reject) => {
+      this.waiter = { resolve, reject };
+      this.flush();
+    });
+  }
+
+  async command(line: string, expected: number[], label: string): Promise<SmtpReply> {
+    if (this.closed) throw this.closed;
+    this.socket.write(`${line}\r\n`);
+    const reply = await this.read();
+    if (!expected.includes(reply.code)) {
+      throw new SmtpError(`${label} 실패: ${reply.code} ${reply.lines.join(' ')}`.trim());
+    }
+    return reply;
+  }
+
+  /** STARTTLS 뒤에는 같은 소켓을 TLS 로 감싸고 인사를 다시 한다. */
+  upgrade(): Promise<void> {
+    const plain = this.socket;
+    plain.removeAllListeners('data');
+    plain.removeAllListeners('timeout');
+    plain.removeAllListeners('error');
+    plain.removeAllListeners('close');
+    plain.setTimeout(0);
+    this.buffer = '';
+    this.pending = [];
+    return new Promise<void>((resolve, reject) => {
+      const secure = tls.connect({
+        socket: plain,
+        servername: this.options.host,
+        rejectUnauthorized: !this.options.skipTlsVerify,
+        minVersion: 'TLSv1.2',
+      });
+      // Track the TLS socket even before the handshake so end() always owns it.
+      this.socket = secure;
+      const timer = setTimeout(() => {
+        settle(new SmtpError(`STARTTLS 시간 초과 (${this.options.timeoutMs}ms)`));
+      }, this.options.timeoutMs);
+      const onError = (error: Error) => settle(new SmtpError(`STARTTLS 실패: ${error.message}`));
+      const onClose = () => settle(new SmtpError('STARTTLS 연결이 끊어졌습니다.'));
+      const onSecureConnect = () => settle();
+      const settle = (error?: Error) => {
+        clearTimeout(timer);
+        secure.removeListener('secureConnect', onSecureConnect);
+        secure.removeListener('error', onError);
+        secure.removeListener('close', onClose);
+        if (error) {
+          this.closed = error;
+          this.end();
+          reject(error);
+          return;
+        }
+        this.attach(secure);
+        resolve();
+      };
+      secure.once('secureConnect', onSecureConnect);
+      secure.once('error', onError);
+      secure.once('close', onClose);
+    });
+  }
+
+  write(data: string) {
+    this.socket.write(data);
+  }
+
+  end() {
+    this.closed ??= new SmtpError('SMTP 연결을 닫았습니다.');
+    this.socket.removeAllListeners('close');
+    this.socket.removeAllListeners('error');
+    this.socket.on('error', () => undefined);
+    this.socket.end();
+    this.socket.destroy();
+  }
+}
+
+function connect(options: SmtpOptions): Promise<SmtpConnection> {
+  return new Promise((resolve, reject) => {
+    const timer = setTimeout(() => {
+      socket.destroy();
+      reject(new SmtpError(`SMTP 연결 시간 초과 (${options.host}:${options.port}, ${options.timeoutMs}ms)`));
+    }, options.timeoutMs);
+    const settle = (error?: Error) => {
+      clearTimeout(timer);
+      if (error) {
+        socket.destroy();
+        reject(new SmtpError(`SMTP 연결 실패 (${options.host}:${options.port}): ${error.message}`));
+        return;
+      }
+      socket.removeListener('error', settle);
+      resolve(new SmtpConnection(socket, options));
+    };
+    const socket: net.Socket = options.security === 'tls'
+      ? tls.connect(
+        { host: options.host, port: options.port, servername: options.host, rejectUnauthorized: !options.skipTlsVerify, minVersion: 'TLSv1.2' },
+        () => settle(),
+      )
+      : net.connect({ host: options.host, port: options.port }, () => settle());
+    socket.once('error', settle);
+  });
+}
+
+function extension(reply: SmtpReply, name: string) {
+  const line = reply.lines.find((entry) => entry.toUpperCase().split(/[ =]/)[0] === name);
+  return line === undefined ? null : line.slice(name.length).replace(/^[ =]/, '').trim();
+}
+
+async function authenticate(connection: SmtpConnection, ehlo: SmtpReply, options: SmtpOptions) {
+  if (!options.username) return;
+  const mechanisms = extension(ehlo, 'AUTH');
+  if (mechanisms === null) {
+    throw new SmtpError('서버가 인증을 지원하지 않습니다. 사용자 이름을 비우고 사용하세요.');
+  }
+  const upper = mechanisms.toUpperCase();
+  if (upper.includes('PLAIN')) {
+    const token = Buffer.from(`\u0000${options.username}\u0000${options.password}`, 'utf-8').toString('base64');
+    await connection.command(`AUTH PLAIN ${token}`, [235], 'AUTH PLAIN');
+    return;
+  }
+  if (upper.includes('LOGIN')) {
+    await connection.command('AUTH LOGIN', [334], 'AUTH LOGIN');
+    await connection.command(Buffer.from(options.username, 'utf-8').toString('base64'), [334], 'AUTH LOGIN 사용자');
+    await connection.command(Buffer.from(options.password, 'utf-8').toString('base64'), [235], 'AUTH LOGIN 비밀번호');
+    return;
+  }
+  throw new SmtpError(`서버가 지원하는 인증 방식(${mechanisms})을 이 앱이 쓰지 못합니다. PLAIN 또는 LOGIN 이 필요합니다.`);
+}
+
+/**
+ * 연결을 열고 메시지 한 통을 보낸다. 실패는 SmtpError 로 이유를 담아 던지고, 어떤 경우에도
+ * 비밀번호는 오류 문장에 들어가지 않는다.
+ */
+export async function sendMail(options: SmtpOptions, envelope: SmtpEnvelope): Promise<void> {
+  const connection = await connect(options);
+  try {
+    const greeting = await connection.read();
+    if (greeting.code !== 220) {
+      throw new SmtpError(`SMTP 인사 실패: ${greeting.code} ${greeting.lines.join(' ')}`.trim());
+    }
+
+    let ehlo = await connection.command(`EHLO ${options.heloName || 'localhost'}`, [250], 'EHLO');
+
+    if (options.security === 'starttls' || options.security === 'auto') {
+      if (extension(ehlo, 'STARTTLS') !== null) {
+        await connection.command('STARTTLS', [220], 'STARTTLS');
+        await connection.upgrade();
+        ehlo = await connection.command(`EHLO ${options.heloName || 'localhost'}`, [250], 'EHLO');
+      } else if (options.security === 'starttls') {
+        throw new SmtpError('서버가 STARTTLS 를 지원하지 않습니다. security 를 auto 나 none 으로 바꾸세요.');
+      }
+    }
+
+    await authenticate(connection, ehlo, options);
+    await connection.command(`MAIL FROM:<${envelope.from}>`, [250], 'MAIL FROM');
+    await connection.command(`RCPT TO:<${envelope.to}>`, [250, 251], 'RCPT TO');
+    await connection.command('DATA', [354], 'DATA');
+    connection.write(envelope.data.endsWith('\r\n') ? envelope.data : `${envelope.data}\r\n`);
+    await connection.command('.', [250], '본문 전송');
+    await connection.command('QUIT', [221], 'QUIT').catch(() => undefined);
+  } finally {
+    connection.end();
+  }
+}
diff --git a/lib/mail/store.ts b/lib/mail/store.ts
new file mode 100644
index 0000000..9a25944
--- /dev/null
+++ b/lib/mail/store.ts
@@ -0,0 +1,134 @@
+import { randomUUID } from 'node:crypto';
+import fs from 'node:fs/promises';
+import path from 'node:path';
+import { defaultMailConfig, normalizeMailConfig, type MailConfig, type MailEvent } from './config.ts';
+
+/**
+ * 메일 설정과 발송 기록은 activity.json 옆의 별도 파일에 둔다(tracking.json 과 같은 규칙).
+ * 파일이 없으면 기본값(꺼짐)이며 아무것도 쓰지 않는다 — 새로 설치한 곳은 달라지지 않는다.
+ */
+function dataDirectory() {
+  return process.env.ACTIVITY_DATA_FILE
+    ? path.dirname(path.resolve(process.env.ACTIVITY_DATA_FILE))
+    : path.join(process.cwd(), 'data');
+}
+
+const MAIL_CONFIG_PATH = process.env.MAIL_CONFIG_FILE
+  ? path.resolve(process.env.MAIL_CONFIG_FILE)
+  : path.join(dataDirectory(), 'mail.json');
+
+const MAIL_DELIVERIES_PATH = process.env.MAIL_DELIVERIES_FILE
+  ? path.resolve(process.env.MAIL_DELIVERIES_FILE)
+  : path.join(dataDirectory(), 'mail-deliveries.json');
+
+/** 최근 것만 남긴다. "안 왔다" 는 문의는 며칠 안에 오고, 훈련 하루에 수백 통이 나가지 않는다. */
+export const MAX_DELIVERIES = 500;
+
+export type DeliveryStatus = 'queued' | 'sent' | 'failed';
+
+/**
+ * 발송 시도 하나. 본문은 담지 않는다 — 제목과 수신자면 충분하고, 본문까지 담으면 알림 기록이
+ * 그 자체로 유출 경로가 된다.
+ */
+export interface Delivery {
+  id: string;
+  event: MailEvent;
+  recipient: string;
+  subject: string;
+  status: DeliveryStatus;
+  attempts: number;
+  error_message: string;
+  created_at: string;
+  updated_at: string;
+}
+
+export interface DeliveryPage {
+  items: Delivery[];
+  summary: { total: number; status: Record<DeliveryStatus, number> };
+}
+
+function isFileNotFound(error: unknown) {
+  return typeof error === 'object' && error !== null && (error as { code?: string }).code === 'ENOENT';
+}
+
+async function writeAtomically(filePath: string, content: string) {
+  const temporaryPath = `${filePath}.${process.pid}.${randomUUID()}.tmp`;
+  await fs.mkdir(path.dirname(filePath), { recursive: true });
+  try {
+    await fs.writeFile(temporaryPath, content, 'utf-8');
+    await fs.rename(temporaryPath, filePath);
+  } finally {
+    await fs.rm(temporaryPath, { force: true }).catch(() => undefined);
+  }
+}
+
+export async function readMailConfig(): Promise<MailConfig> {
+  try {
+    return normalizeMailConfig(JSON.parse(await fs.readFile(MAIL_CONFIG_PATH, 'utf-8')));
+  } catch (error) {
+    if (isFileNotFound(error)) return defaultMailConfig();
+    // 손상된 파일은 꺼진 것과 같이 다룬다. 메일이 빠지는 편이 상황판이 멎는 것보다 낫다.
+    console.error(`mail.json 을 읽지 못해 메일 알림을 끈 상태로 동작합니다 (${MAIL_CONFIG_PATH}):`, error);
+    return defaultMailConfig();
+  }
+}
+
+export async function writeMailConfig(config: MailConfig) {
+  await writeAtomically(MAIL_CONFIG_PATH, JSON.stringify(config, null, 2));
+}
+
+/**
+ * 발송 기록은 배경 작업 여러 개가 거의 동시에 쓴다. Next 는 라우트마다 모듈을 따로 묶을 수
+ * 있으므로 globalThis 에 건 약속 사슬로 쓰기를 한 줄로 세운다.
+ */
+const QUEUE_KEY = '__cutoverMailDeliveryQueue';
+
+function withDeliveryLock<T>(task: () => Promise<T>): Promise<T> {
+  const store = globalThis as typeof globalThis & { [QUEUE_KEY]?: Promise<unknown> };
+  const previous = store[QUEUE_KEY] ?? Promise.resolve();
+  const next = previous.catch(() => undefined).then(task);
+  store[QUEUE_KEY] = next.catch(() => undefined);
+  return next;
+}
+
+async function readDeliveries(): Promise<Delivery[]> {
+  try {
+    const parsed: unknown = JSON.parse(await fs.readFile(MAIL_DELIVERIES_PATH, 'utf-8'));
+    return Array.isArray(parsed) ? parsed as Delivery[] : [];
+  } catch (error) {
+    if (!isFileNotFound(error)) {
+      console.error(`mail-deliveries.json 을 읽지 못해 기록을 새로 시작합니다 (${MAIL_DELIVERIES_PATH}):`, error);
+    }
+    return [];
+  }
+}
+
+/** 새 기록을 맨 앞에 넣는다(최신순). 넘치면 오래된 것부터 버린다. */
+export function recordDelivery(delivery: Delivery) {
+  return withDeliveryLock(async () => {
+    const deliveries = await readDeliveries();
+    deliveries.unshift(delivery);
+    await writeAtomically(MAIL_DELIVERIES_PATH, JSON.stringify(deliveries.slice(0, MAX_DELIVERIES), null, 2));
+  });
+}
+
+export function updateDelivery(id: string, patch: Partial<Pick<Delivery, 'status' | 'attempts' | 'error_message'>>) {
+  return withDeliveryLock(async () => {
+    const deliveries = await readDeliveries();
+    const index = deliveries.findIndex((delivery) => delivery.id === id);
+    if (index === -1) return;
+    deliveries[index] = { ...deliveries[index], ...patch, updated_at: new Date().toISOString() };
+    await writeAtomically(MAIL_DELIVERIES_PATH, JSON.stringify(deliveries, null, 2));
+  });
+}
+
+export async function listDeliveries(options: { status?: string; limit?: number } = {}): Promise<DeliveryPage> {
+  const deliveries = await withDeliveryLock(readDeliveries);
+  const summary: DeliveryPage['summary'] = { total: deliveries.length, status: { queued: 0, sent: 0, failed: 0 } };
+  for (const delivery of deliveries) {
+    if (delivery.status in summary.status) summary.status[delivery.status] += 1;
+  }
+  const limit = options.limit && options.limit >= 1 && options.limit <= 200 ? options.limit : 50;
+  const filtered = options.status ? deliveries.filter((delivery) => delivery.status === options.status) : deliveries;
+  return { items: filtered.slice(0, limit), summary };
+}
