+import assert from 'node:assert/strict';
+import { describe, it } from 'node:test';
+import {
+  addAllowedHost,
+  buildPagePolicy,
+  defaultTrackingConfig,
+  isTrackingActive,
+  MAX_SNIPPET_BYTES,
+  normalizeTrackingConfig,
+  parseSnippetScripts,
+  policySources,
+  renderSnippetScripts,
+  serializeSnippetScripts,
+  snippetOrigins,
+  sourceAllows,
+  validateTrackingConfig,
+  type TrackingConfig,
+} from './core.ts';
+
+const NONCE = 'test-nonce';
+
+function momentoConfig(overrides: Partial<TrackingConfig> = {}): TrackingConfig {
+  return {
+    ...defaultTrackingConfig(),
+    enabled: true,
+    provider: 'momento',
+    momento_url: 'https://momento.corp.example/',
+    momento_site_id: 'cutover',
+    ...overrides,
+  };
+}
+
+describe('기본값', () => {
+  it('꺼져 있고 provider 는 none 이다', () => {
+    const config = defaultTrackingConfig();
+    assert.equal(config.enabled, false);
+    assert.equal(config.provider, 'none');
+    assert.equal(config.placement, 'head');
+    assert.equal(config.include_admin, false);
+    assert.equal(config.momento_proxy, true);
+  });
+
+  it('모르는 값은 기본값으로 돌아간다', () => {
+    const config = normalizeTrackingConfig({ enabled: 'yes', provider: 'pixel', placement: 'footer', momento_proxy: false });
+    assert.equal(config.enabled, false);
+    assert.equal(config.provider, 'none');
+    assert.equal(config.placement, 'head');
+    assert.equal(config.momento_proxy, false);
+    assert.deepEqual(normalizeTrackingConfig(null), defaultTrackingConfig());
+  });
+});
+
+describe('스니펫 렌더링', () => {
+  it('꺼져 있으면 어떤 경로에도 붙지 않는다', () => {
+    const config = momentoConfig({ enabled: false });
+    assert.equal(isTrackingActive(config, '/'), false);
+    assert.equal(isTrackingActive(config, '/pc'), false);
+  });
+
+  it('Momento 는 프록시 경로를 기본으로 쓰고 외부 출처가 정책에 나오지 않는다', () => {
+    const [script] = renderSnippetScripts(momentoConfig());
+    assert.equal(script.src, '/momento/tracker.js');
+    assert.equal(script.attributes['data-endpoint'], '/momento');
+    assert.equal(script.attributes['data-site-id'], 'cutover');
+    assert.equal(script.attributes['data-environment'], 'prd');
+    assert.equal(script.attributes['data-contract-version'], '1');
+    assert.equal(script.attributes.async, true);
+    assert.deepEqual(policySources(momentoConfig()), { scripts: [], connects: [], images: [] });
+  });
+
+  it('Momento 프록시를 끄면 수집기 출처가 정책에 더해진다', () => {
+    const config = momentoConfig({ momento_proxy: false });
+    assert.equal(renderSnippetScripts(config)[0].src, 'https://momento.corp.example/tracker.js');
+    assert.deepEqual(policySources(config).scripts, ['https://momento.corp.example']);
+    assert.deepEqual(policySources(config).connects, ['https://momento.corp.example']);
