+/** 브라우저가 차단한 요청을 신고하는 경로. 추적이 켜진 동안에만 정책에 들어간다. */
+export const CSP_REPORT_PATH = '/api/csp-report';
+
+export interface TrackingConfig {
+  enabled: boolean;
+  provider: TrackingProvider;
+  momento_url: string;
+  momento_site_id: string;
+  momento_environment: string;
+  /** 켜면 /momento/* 를 통해 수집기로 넘겨 외부 출처가 정책에 등장하지 않는다. */
+  momento_proxy: boolean;
+  measurement_id: string;
+  matomo_url: string;
+  matomo_site_id: string;
+  custom_snippet: string;
+  allowed_hosts: string;
+  include_admin: boolean;
+  placement: TrackingPlacement;
+}
+
+export interface TrackingValidationIssue {
+  path: string;
+  message: string;
+}
+
+export class TrackingValidationError extends Error {
+  issues: TrackingValidationIssue[];
+
+  constructor(issues: TrackingValidationIssue[]) {
+    super('추적 설정이 올바르지 않습니다.');
+    this.name = 'TrackingValidationError';
+    this.issues = issues;
+  }
+}
+
+/** 삽입할 <script> 하나. 문자열이 아니라 구조로 두어 React 가 속성을 이스케이프한다. */
+export interface SnippetScript {
+  src?: string;
+  inline?: string;
+  attributes: Record<string, string | true>;
+}
+
+export interface PolicySources {
+  scripts: string[];
+  connects: string[];
+  images: string[];
+}
+
+export function defaultTrackingConfig(): TrackingConfig {
+  return {
+    enabled: false,
+    provider: 'none',
+    momento_url: '',
+    momento_site_id: '',
+    momento_environment: 'prd',
+    momento_proxy: true,
+    measurement_id: '',
+    matomo_url: '',
+    matomo_site_id: '',
+    custom_snippet: '',
+    allowed_hosts: '',
+    include_admin: false,
+    placement: 'head',
+  };
+}
+
+function isRecord(value: unknown): value is Record<string, unknown> {
+  return typeof value === 'object' && value !== null && !Array.isArray(value);
+}
+
+function stringField(value: unknown, fallback: string) {
+  return typeof value === 'string' ? value.trim() : fallback;
+}
+
+/** 저장된 값이 어떤 모양이든 완전한 설정으로 맞춘다. 모르는 값은 기본값으로 돌아간다. */
+export function normalizeTrackingConfig(value: unknown): TrackingConfig {
+  const defaults = defaultTrackingConfig();
+  if (!isRecord(value)) return defaults;
+
+  const provider = stringField(value.provider, defaults.provider).toLowerCase();
+  const placement = stringField(value.placement, defaults.placement).toLowerCase();
+
+  return {
+    enabled: value.enabled === true,
+    provider: (TRACKING_PROVIDERS as readonly string[]).includes(provider) ? provider as TrackingProvider : 'none',
+    momento_url: stringField(value.momento_url, ''),
+    momento_site_id: stringField(value.momento_site_id, ''),
+    momento_environment: stringField(value.momento_environment, defaults.momento_environment) || defaults.momento_environment,
+    momento_proxy: value.momento_proxy !== false,
+    measurement_id: stringField(value.measurement_id, ''),
+    matomo_url: stringField(value.matomo_url, ''),
+    matomo_site_id: stringField(value.matomo_site_id, ''),
+    custom_snippet: typeof value.custom_snippet === 'string' ? value.custom_snippet.trim() : '',
