+  if (config.momento_url && !originOf(config.momento_url)) {
+    issues.push({ path: 'momento_url', message: 'momento_url 은 http(s) 로 시작하는 주소여야 합니다.' });
+  }
+  if (config.matomo_url && !originOf(config.matomo_url)) {
+    issues.push({ path: 'matomo_url', message: 'matomo_url 은 http(s) 로 시작하는 주소여야 합니다.' });
+  }
+  if (!/^[A-Za-z0-9._-]*$/.test(config.momento_environment)) {
+    issues.push({ path: 'momento_environment', message: 'momento_environment 는 영문·숫자·._- 만 쓸 수 있습니다.' });
+  }
+
+  if (!config.enabled) return issues;
+
+  switch (config.provider) {
+    case 'momento':
+      if (!config.momento_url || !config.momento_site_id) {
