+        issues.push({ path: 'measurement_id', message: 'measurement_id 는 영문·숫자·하이픈만 쓸 수 있습니다.' });
+      }
+      break;
+    case 'matomo':
+      if (!config.matomo_url || !config.matomo_site_id) {
+        issues.push({ path: 'matomo_url', message: 'Matomo 는 matomo_url 과 matomo_site_id 가 필요합니다.' });
+      }
+      break;
+    case 'custom':
+      if (!config.custom_snippet) {
+        issues.push({ path: 'custom_snippet', message: '직접 입력 방식은 추적 코드를 붙여 넣어야 합니다.' });
+      } else if (parseSnippetScripts(config.custom_snippet).length === 0) {
+        issues.push({ path: 'custom_snippet', message: '추적 코드에 <script> 태그가 없습니다. <script> 태그만 삽입됩니다.' });
+      }
+      break;
+    default:
+      break;
+  }
