+import assert from 'node:assert/strict';
+import { describe, it } from 'node:test';
+import { defaultTrackingConfig } from './core.ts';
+import { MAX_VIOLATIONS, ViolationRecorder } from './violations.ts';
+
+describe('차단 기록', () => {
+  it('출처와 지시어를 기억하고 같은 출처는 쌓이지 않는다', () => {
+    const recorder = new ViolationRecorder();
+    recorder.record('https://t.corp.example/t.js?v=1', 'script-src-elem', '/pc');
+    recorder.record('https://t.corp.example/collect', 'script-src-elem', '/');
+    recorder.record('https://t.corp.example/collect', 'connect-src', '/');
+
+    const list = recorder.list(defaultTrackingConfig());
+    assert.equal(list.length, 2);
+    const script = list.find((item) => item.directive === 'script-src-elem');
+    assert.equal(script?.origin, 'https://t.corp.example');
+    assert.equal(script?.count, 2);
+    assert.equal(script?.page, '/');
+    assert.equal(script?.allowed, false);
+  });
+
+  it('http 출처가 아닌 것은 버리고 지시어가 없으면 connect-src 로 둔다', () => {
+    const recorder = new ViolationRecorder();
+    recorder.record('chrome-extension://abc/x.js', 'script-src', '/');
+    recorder.record('data', 'img-src', '/');
+    recorder.record('inline', 'script-src', '/');
+    recorder.record('https://p.example/p.gif', '', '/');
+    const list = recorder.list(defaultTrackingConfig());
+    assert.equal(list.length, 1);
+    assert.equal(list[0].directive, 'connect-src');
+  });
+
+  it('현재 설정이 허용하는 출처는 표시된다', () => {
+    const recorder = new ViolationRecorder();
+    recorder.record('https://region1.google-analytics.com/g/collect', 'connect-src', '/');
+    recorder.record('https://other.example/x', 'connect-src', '/');
+    const list = recorder.list({ ...defaultTrackingConfig(), enabled: true, provider: 'ga4', measurement_id: 'G-1' });
+    assert.equal(list.find((item) => item.origin.includes('google-analytics'))?.allowed, true);
+    assert.equal(list.find((item) => item.origin.includes('other.example'))?.allowed, false);
+  });
+
+  it('고리 버퍼는 가장 오래된 것을 밀어낸다', () => {
+    let clock = 0;
+    const recorder = new ViolationRecorder(() => (clock += 1000));
+    for (let index = 0; index < MAX_VIOLATIONS + 5; index += 1) {
+      recorder.record(`https://host-${index}.example`, 'img-src', '/');
+    }
+    const list = recorder.list(defaultTrackingConfig());
+    assert.equal(list.length, MAX_VIOLATIONS);
+    assert.equal(list[0].origin, `https://host-${MAX_VIOLATIONS + 4}.example`);
+    assert.ok(!list.some((item) => item.origin === 'https://host-0.example'));
+
+    recorder.forget();
+    assert.equal(recorder.size, 0);
+  });
+});
