for (const security of ['auto', 'starttls'] as const) {
  it(`${security}: STARTTLS 승인 뒤 TLS 무응답이면 시간 초과로 끝나고 연결을 닫는다`, async () => {
    const sockets = new Set<net.Socket>();
    let handshakeStarted = false;
    let peerClosed = false;
    const server = net.createServer((socket) => {
      sockets.add(socket);
      socket.on('error', () => undefined);
      socket.on('close', () => { peerClosed = true; sockets.delete(socket); });
      socket.write('220 relay ready\r\n');
      let buffer = '';
      let upgrading = false;
      socket.on('data', (chunk) => {
        if (upgrading) { handshakeStarted = true; return; }
        buffer += chunk.toString();
        let index: number;
        while ((index = buffer.indexOf('\r\n')) !== -1) {
          const line = buffer.slice(0, index);
          buffer = buffer.slice(index + 2);
          if (line.startsWith('EHLO ')) socket.write('250-relay\r\n250 STARTTLS\r\n');
          if (line === 'STARTTLS') {
            upgrading = true;
            socket.write('220 begin TLS\r\n');
          }
        }
      });
    });
    server.listen(0, '127.0.0.1');
    await once(server, 'listening');
    const address = server.address() as net.AddressInfo;
    let watchdog: ReturnType<typeof setTimeout> | undefined;
    try {
      const deadline = new Promise<never>((_, reject) => {
        watchdog = setTimeout(() => reject(new Error('sendMail STILL_PENDING after 1000ms')), 1000);
      });
      await assert.rejects(
        Promise.race([sendMail(optionsFor({ host: '127.0.0.1', port: address.port }, {
          security, timeoutMs: 100,
        }), envelope()), deadline]),
        (error: unknown) => error instanceof SmtpError && /STARTTLS.*시간 초과/.test(error.message),
      );
      assert.equal(handshakeStarted, true);
      // Give the relay time to observe the client's socket cleanup.
      for (let i = 0; i < 50 && !peerClosed; i++) {
        await new Promise((resolve) => setTimeout(resolve, 10));
      }
      assert.equal(peerClosed, true, 'client must close the stalled TLS connection');
    } finally {
      clearTimeout(watchdog);
      for (const socket of sockets) socket.destroy();
      await new Promise<void>((resolve) => server.close(() => resolve()));
    }
  });
}

