import { NextRequest, NextResponse } from 'next/server';
import { readTrackingConfig } from '@/lib/tracking/store';

export const runtime = 'nodejs';

/** 수집 이벤트는 작다. 이보다 큰 본문은 넘기지 않는다. */
const MAX_BODY_BYTES = 256 * 1024;
const UPSTREAM_TIMEOUT_MS = 10_000;
const FORWARDED_REQUEST_HEADERS = ['accept', 'content-type', 'user-agent', 'referer', 'accept-language'];
const FORWARDED_RESPONSE_HEADERS = ['content-type', 'cache-control', 'etag', 'last-modified'];

/**
 * Momento 같은 오리진 프록시. 브라우저는 /momento/* 만 보고, 앱이 그 요청을 수집기로 넘긴다.
 * 그래서 CSP 에 외부 출처를 넣지 않아도 되고, 브라우저에서 수집기가 직접 닿지 않는 망에서도
 * 동작한다. 추적이 Momento 로 켜져 있고 프록시 사용이 켜진 동안에만 열린다.
 */
async function forward(request: NextRequest, path: string[]) {
  const config = await readTrackingConfig();
  if (!config.enabled || config.provider !== 'momento' || !config.momento_proxy || !config.momento_url) {
    return new NextResponse(null, { status: 404 });
  }

  const contentLength = Number(request.headers.get('content-length'));
  if (Number.isFinite(contentLength) && contentLength > MAX_BODY_BYTES) {
    return new NextResponse(null, { status: 413 });
  }

  let upstream: URL;
  try {
    upstream = new URL(path.map(encodeURIComponent).join('/'), `${config.momento_url.replace(/\/+$/, '')}/`);
    upstream.search = request.nextUrl.search;
  } catch {
    return new NextResponse(null, { status: 502 });
  }

  const headers = new Headers();
  for (const name of FORWARDED_REQUEST_HEADERS) {
    const value = request.headers.get(name);
    if (value) headers.set(name, value);
  }
  // 수집기가 방문자 주소를 알 수 있게 넘긴다. 앞단 프록시가 이미 적어 둔 값을 이어 쓴다.
  const forwardedFor = request.headers.get('x-forwarded-for');
  if (forwardedFor) headers.set('x-forwarded-for', forwardedFor);
  headers.set('x-forwarded-host', request.headers.get('host') ?? request.nextUrl.host);
  headers.set('x-forwarded-proto', request.nextUrl.protocol.replace(':', ''));

  let body: ArrayBuffer | undefined;
  if (request.method !== 'GET' && request.method !== 'HEAD') {
    body = await request.arrayBuffer();
    if (body.byteLength > MAX_BODY_BYTES) return new NextResponse(null, { status: 413 });
  }

  try {
    const response = await fetch(upstream, {
      method: request.method,
      headers,
      body,
      redirect: 'manual',
      cache: 'no-store',
      signal: AbortSignal.timeout(UPSTREAM_TIMEOUT_MS),
    });
    const responseHeaders = new Headers();
    for (const name of FORWARDED_RESPONSE_HEADERS) {
      const value = response.headers.get(name);
      if (value) responseHeaders.set(name, value);
    }
    return new NextResponse(response.body, { status: response.status, headers: responseHeaders });
  } catch (error) {
    console.error(`Momento 프록시 전달 실패 (${upstream.origin}):`, error);
    return new NextResponse(null, { status: 502 });
  }
}

type Context = { params: Promise<{ path: string[] }> };

export async function GET(request: NextRequest, context: Context) {
  return forward(request, (await context.params).path);
}

export async function POST(request: NextRequest, context: Context) {
  return forward(request, (await context.params).path);
}
import { randomUUID } from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import {
  defaultTrackingConfig,
  normalizeTrackingConfig,
  type TrackingConfig,
} from './core.ts';

/**
 * 추적 설정은 activity.json 옆의 별도 파일에 둔다. 빌드 시점 환경 변수로만 받으면
 * 수집 서버 주소가 바뀔 때마다 다시 배포해야 하고, 그런 설정은 결국 꺼진 채로 남는다.
 * 파일이 없으면 기본값(꺼짐)이며 아무것도 쓰지 않는다 — 새로 설치한 곳은 달라지지 않는다.
 */
const TRACKING_CONFIG_PATH = process.env.TRACKING_CONFIG_FILE
  ? path.resolve(process.env.TRACKING_CONFIG_FILE)
  : process.env.ACTIVITY_DATA_FILE
    ? path.join(path.dirname(path.resolve(process.env.ACTIVITY_DATA_FILE)), 'tracking.json')
    : path.join(process.cwd(), 'data', 'tracking.json');

function isFileNotFound(error: unknown) {
  return typeof error === 'object' && error !== null && (error as { code?: string }).code === 'ENOENT';
}

interface CacheEntry {
  mtimeMs: number;
  size: number;
  config: TrackingConfig;
}

let cache: CacheEntry | null = null;

/**
 * 요청마다 호출된다(프록시와 레이아웃). 파일 메타데이터가 그대로면 마지막 결과를 돌려주므로
 * 페이지를 열 때마다 JSON 을 다시 읽지 않는다.
 */
export async function readTrackingConfig(): Promise<TrackingConfig> {
  let stat;
  try {
    stat = await fs.stat(TRACKING_CONFIG_PATH);
  } catch (error) {
    if (isFileNotFound(error)) {
      cache = null;
      return defaultTrackingConfig();
    }
    throw error;
  }

  if (cache && cache.mtimeMs === stat.mtimeMs && cache.size === stat.size) return cache.config;

  try {
    const config = normalizeTrackingConfig(JSON.parse(await fs.readFile(TRACKING_CONFIG_PATH, 'utf-8')));
    cache = { mtimeMs: stat.mtimeMs, size: stat.size, config };
    return config;
  } catch (error) {
    if (isFileNotFound(error)) return defaultTrackingConfig();
    // 손상된 파일은 추적을 끈 것과 같이 다룬다. 화면이 깨지는 것보다 수집이 빠지는 편이 낫다.
    console.error(`tracking.json 을 읽지 못해 추적을 끈 상태로 동작합니다 (${TRACKING_CONFIG_PATH}):`, error);
    return defaultTrackingConfig();
  }
}

export async function writeTrackingConfig(config: TrackingConfig) {
  const directory = path.dirname(TRACKING_CONFIG_PATH);
  const temporaryPath = `${TRACKING_CONFIG_PATH}.${process.pid}.${randomUUID()}.tmp`;

  await fs.mkdir(directory, { recursive: true });
  try {
    await fs.writeFile(temporaryPath, JSON.stringify(config, null, 2), 'utf-8');
    await fs.rename(temporaryPath, TRACKING_CONFIG_PATH);
  } finally {
    await fs.rm(temporaryPath, { force: true }).catch(() => undefined);
  }
  cache = null;
}
import { randomUUID } from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import { defaultMailConfig, normalizeMailConfig, type MailConfig, type MailEvent } from './config.ts';

/**
 * 메일 설정과 발송 기록은 activity.json 옆의 별도 파일에 둔다(tracking.json 과 같은 규칙).
 * 파일이 없으면 기본값(꺼짐)이며 아무것도 쓰지 않는다 — 새로 설치한 곳은 달라지지 않는다.
 */
function dataDirectory() {
  return process.env.ACTIVITY_DATA_FILE
    ? path.dirname(path.resolve(process.env.ACTIVITY_DATA_FILE))
    : path.join(process.cwd(), 'data');
}

const MAIL_CONFIG_PATH = process.env.MAIL_CONFIG_FILE
  ? path.resolve(process.env.MAIL_CONFIG_FILE)
  : path.join(dataDirectory(), 'mail.json');

const MAIL_DELIVERIES_PATH = process.env.MAIL_DELIVERIES_FILE
  ? path.resolve(process.env.MAIL_DELIVERIES_FILE)
  : path.join(dataDirectory(), 'mail-deliveries.json');

/** 최근 것만 남긴다. "안 왔다" 는 문의는 며칠 안에 오고, 훈련 하루에 수백 통이 나가지 않는다. */
export const MAX_DELIVERIES = 500;

export type DeliveryStatus = 'queued' | 'sent' | 'failed';

/**
 * 발송 시도 하나. 본문은 담지 않는다 — 제목과 수신자면 충분하고, 본문까지 담으면 알림 기록이
 * 그 자체로 유출 경로가 된다.
 */
export interface Delivery {
  id: string;
  event: MailEvent;
  recipient: string;
  subject: string;
  status: DeliveryStatus;
  attempts: number;
  error_message: string;
  created_at: string;
  updated_at: string;
}

export interface DeliveryPage {
  items: Delivery[];
  summary: { total: number; status: Record<DeliveryStatus, number> };
}

function isFileNotFound(error: unknown) {
  return typeof error === 'object' && error !== null && (error as { code?: string }).code === 'ENOENT';
}

async function writeAtomically(filePath: string, content: string) {
  const temporaryPath = `${filePath}.${process.pid}.${randomUUID()}.tmp`;
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  try {
    await fs.writeFile(temporaryPath, content, 'utf-8');
    await fs.rename(temporaryPath, filePath);
  } finally {
    await fs.rm(temporaryPath, { force: true }).catch(() => undefined);
  }
}

export async function readMailConfig(): Promise<MailConfig> {
  try {
    return normalizeMailConfig(JSON.parse(await fs.readFile(MAIL_CONFIG_PATH, 'utf-8')));
  } catch (error) {
    if (isFileNotFound(error)) return defaultMailConfig();
    // 손상된 파일은 꺼진 것과 같이 다룬다. 메일이 빠지는 편이 상황판이 멎는 것보다 낫다.
    console.error(`mail.json 을 읽지 못해 메일 알림을 끈 상태로 동작합니다 (${MAIL_CONFIG_PATH}):`, error);
    return defaultMailConfig();
  }
}

export async function writeMailConfig(config: MailConfig) {
  await writeAtomically(MAIL_CONFIG_PATH, JSON.stringify(config, null, 2));
}

/**
 * 발송 기록은 배경 작업 여러 개가 거의 동시에 쓴다. Next 는 라우트마다 모듈을 따로 묶을 수
 * 있으므로 globalThis 에 건 약속 사슬로 쓰기를 한 줄로 세운다.
 */
const QUEUE_KEY = '__cutoverMailDeliveryQueue';

function withDeliveryLock<T>(task: () => Promise<T>): Promise<T> {
  const store = globalThis as typeof globalThis & { [QUEUE_KEY]?: Promise<unknown> };
  const previous = store[QUEUE_KEY] ?? Promise.resolve();
  const next = previous.catch(() => undefined).then(task);
  store[QUEUE_KEY] = next.catch(() => undefined);
  return next;
}

async function readDeliveries(): Promise<Delivery[]> {
  try {
    const parsed: unknown = JSON.parse(await fs.readFile(MAIL_DELIVERIES_PATH, 'utf-8'));
    return Array.isArray(parsed) ? parsed as Delivery[] : [];
  } catch (error) {
    if (!isFileNotFound(error)) {
      console.error(`mail-deliveries.json 을 읽지 못해 기록을 새로 시작합니다 (${MAIL_DELIVERIES_PATH}):`, error);
    }
    return [];
  }
}

/** 새 기록을 맨 앞에 넣는다(최신순). 넘치면 오래된 것부터 버린다. */
export function recordDelivery(delivery: Delivery) {
  return withDeliveryLock(async () => {
    const deliveries = await readDeliveries();
    deliveries.unshift(delivery);
    await writeAtomically(MAIL_DELIVERIES_PATH, JSON.stringify(deliveries.slice(0, MAX_DELIVERIES), null, 2));
  });
}

export function updateDelivery(id: string, patch: Partial<Pick<Delivery, 'status' | 'attempts' | 'error_message'>>) {
  return withDeliveryLock(async () => {
    const deliveries = await readDeliveries();
    const index = deliveries.findIndex((delivery) => delivery.id === id);
    if (index === -1) return;
    deliveries[index] = { ...deliveries[index], ...patch, updated_at: new Date().toISOString() };
    await writeAtomically(MAIL_DELIVERIES_PATH, JSON.stringify(deliveries, null, 2));
  });
}

export async function listDeliveries(options: { status?: string; limit?: number } = {}): Promise<DeliveryPage> {
  const deliveries = await withDeliveryLock(readDeliveries);
  const summary: DeliveryPage['summary'] = { total: deliveries.length, status: { queued: 0, sent: 0, failed: 0 } };
  for (const delivery of deliveries) {
    if (delivery.status in summary.status) summary.status[delivery.status] += 1;
  }
  const limit = options.limit && options.limit >= 1 && options.limit <= 200 ? options.limit : 50;
  const filtered = options.status ? deliveries.filter((delivery) => delivery.status === options.status) : deliveries;
  return { items: filtered.slice(0, limit), summary };
}

import { NextRequest, NextResponse } from 'next/server';
import { isAdminRequest } from '@/lib/adminSession';
import { normalizeMailConfig, publicMailConfig, validateMailConfig } from '@/lib/mail/config';
import { readMailConfig, writeMailConfig } from '@/lib/mail/store';

export const runtime = 'nodejs';

function unauthorizedResponse() {
  return NextResponse.json(
    { error: '관리자 인증이 만료되었습니다. 다시 로그인해 주세요.', code: 'UNAUTHORIZED' },
    { status: 401 },
  );
}

/** 설정 조회. 비밀번호는 돌려주지 않는다 — `password_set` 으로 "설정됨" 만 알린다. */
export async function GET(request: NextRequest) {
  if (!isAdminRequest(request)) return unauthorizedResponse();

  try {
    return NextResponse.json({ config: publicMailConfig(await readMailConfig()) }, { headers: { 'Cache-Control': 'no-store' } });
  } catch (error) {
    console.error('GET /api/mail failed:', error);
    return NextResponse.json({ error: '메일 설정을 읽지 못했습니다.' }, { status: 500 });
  }
}

/**
 * 설정 저장. 본문에 `password` 가 없거나 빈 문자열이면 기존 비밀번호를 유지하고,
 * `password_clear: true` 로만 지운다. 저장한 설정은 다음 알림부터 바로 쓰인다.
 */
export async function PUT(request: NextRequest) {
  if (!isAdminRequest(request)) return unauthorizedResponse();

  try {
    const body: unknown = await request.json();
    if (typeof body !== 'object' || body === null || Array.isArray(body)) {
      return NextResponse.json({ error: '요청 본문은 JSON 객체여야 합니다.' }, { status: 400 });
    }

    const config = normalizeMailConfig(body, await readMailConfig());
    const issues = validateMailConfig(config);
    if (issues.length > 0) {
      return NextResponse.json(
