    { error: '관리자 인증이 만료되었습니다. 다시 로그인해 주세요.', code: 'UNAUTHORIZED' },
    { status: 401 },
  );
}

/** 관리 화면이 설정과 함께 "정책에 어떤 출처가 더해지는가" 를 보여 줄 수 있게 같이 내려 준다. */
function describe(config: TrackingConfig) {
