export async function PUT(request: NextRequest) {
  if (!isAdminRequest(request)) return unauthorizedResponse();

  try {
    const body: unknown = await request.json();
    if (typeof body !== 'object' || body === null || Array.isArray(body)) {
      return NextResponse.json({ error: '요청 본문은 JSON 객체여야 합니다.' }, { status: 400 });
    }

    const config = normalizeTrackingConfig(body);
    const issues = validateTrackingConfig(config);
    if (issues.length > 0) {
      return NextResponse.json(
        { error: '추적 설정이 올바르지 않습니다.', code: 'INVALID_TRACKING_CONFIG', details: issues },
        { status: 400 },
      );
    }

    await writeTrackingConfig(config);
    return NextResponse.json(describe(config));
