    if (error instanceof SyntaxError) {
      return NextResponse.json({ error: '요청 JSON 문법이 올바르지 않습니다.' }, { status: 400 });
    }

    console.error('PUT /api/tracking failed:', error);
    return NextResponse.json({ error: '추적 설정을 저장하지 못했습니다.' }, { status: 500 });
  }
}
