export default function TrackingSnippet({ scripts, nonce }: { scripts: SnippetScript[]; nonce: string }) {
  return (
    <>
      {scripts.map((script, index) => {
        const props: Record<string, string | boolean> = { nonce };
        for (const [name, value] of Object.entries(script.attributes)) {
          props[ATTRIBUTE_PROP_NAMES[name] ?? name] = value;
