          return <script key={index} {...props} src={script.src} data-tracking-snippet="" />;
        }
        return (
          <script
            key={index}
            {...props}
            data-tracking-snippet=""
            dangerouslySetInnerHTML={{ __html: script.inline ?? '' }}
          />
        );
      })}
    </>
  );
}
