import { createHmac, timingSafeEqual } from 'node:crypto';
import type { NextRequest } from 'next/server';

export const ADMIN_SESSION_COOKIE = 'cutover_admin_session';
export const ADMIN_SESSION_MAX_AGE = 60 * 60 * 24 * 7;

function getAdminPassword() {
  return process.env.ADMIN_PASSWORD ?? process.env.NEXT_PUBLIC_ADMIN_PASSWORD ?? '';
}

function getSigningSecret() {
  return process.env.AUTH_SECRET ?? getAdminPassword();
}

function sign(payload: string) {
  const secret = getSigningSecret();
  if (!secret) return '';

  return createHmac('sha256', secret).update(payload).digest('base64url');
}

function safeEqual(left: string, right: string) {
  const leftBuffer = Buffer.from(left);
  const rightBuffer = Buffer.from(right);

  return leftBuffer.length === rightBuffer.length && timingSafeEqual(leftBuffer, rightBuffer);
}

export function isCorrectPassword(role: 'admin' | 'user', password: string) {
  const expected = role === 'admin'
    ? getAdminPassword()
    : (process.env.USER_PASSWORD ?? process.env.NEXT_PUBLIC_USER_PASSWORD ?? '');

  return Boolean(expected) && safeEqual(password, expected);
}

export function createAdminSessionToken() {
  const expiresAt = Date.now() + (ADMIN_SESSION_MAX_AGE * 1000);
  const payload = `admin.${expiresAt}`;
  const signature = sign(payload);

  return signature ? `${payload}.${signature}` : '';
}

export function verifyAdminSessionToken(token: string | undefined) {
  if (!token) return false;

  const parts = token.split('.');
  if (parts.length !== 3 || parts[0] !== 'admin') return false;

  const expiresAt = Number(parts[1]);
  if (!Number.isSafeInteger(expiresAt) || expiresAt <= Date.now()) return false;

  const payload = `${parts[0]}.${parts[1]}`;
  const expectedSignature = sign(payload);

  return Boolean(expectedSignature) && safeEqual(parts[2], expectedSignature);
}

export function isAdminRequest(request: NextRequest) {
  return verifyAdminSessionToken(request.cookies.get(ADMIN_SESSION_COOKIE)?.value);
}

export interface AdminCookieSecureInput {
  /** ADMIN_COOKIE_SECURE 환경 변수 값. true/false 로 강제하고, 비어 있거나 auto 면 요청 프로토콜을 따른다. */
  setting?: string;
  /** X-Forwarded-Proto 헤더. 리버스 프록시가 HTTPS 를 종단하면 'https' 가 온다. 여러 개면 첫 값만 본다. */
  forwardedProto?: string | null;
  /** 앱 서버가 직접 받은 요청의 프로토콜('https:' 또는 'http:'). */
  protocol?: string;
}

const SECURE_ON = new Set(['true', '1', 'yes', 'on']);
const SECURE_OFF = new Set(['false', '0', 'no', 'off']);

/**
 * 관리자 세션 쿠키에 Secure 속성을 붙일지 정한다.
 * 브라우저는 평문 HTTP(localhost 제외)에서 Secure 쿠키를 저장하지 않으므로, HTTPS 없이 사내망에 띄운
 * 운영 빌드에서 관리자 로그인이 되도록 기본은 요청이 실제로 HTTPS 로 왔을 때만 붙인다.
 */
export function resolveAdminCookieSecure(input: AdminCookieSecureInput) {
  const setting = (input.setting ?? '').trim().toLowerCase();
  if (SECURE_ON.has(setting)) return true;
  if (SECURE_OFF.has(setting)) return false;

  const forwarded = (input.forwardedProto ?? '').split(',')[0].trim().toLowerCase();
  if (forwarded) return forwarded === 'https';

  return (input.protocol ?? '').toLowerCase() === 'https:';
}

export function shouldSecureAdminCookie(request: NextRequest) {
  return resolveAdminCookieSecure({
    setting: process.env.ADMIN_COOKIE_SECURE,
    forwardedProto: request.headers.get('x-forwarded-proto'),
    protocol: request.nextUrl.protocol,
  });
}
