function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function stringField(value: unknown, fallback: string) {
  return typeof value === 'string' ? value.trim() : fallback;
}

function booleanField(value: unknown, fallback: boolean) {
  return typeof value === 'boolean' ? value : fallback;
}

function integerField(value: unknown, fallback: number) {
  const number = typeof value === 'string' && value.trim() !== '' ? Number(value) : value;
  return typeof number === 'number' && Number.isFinite(number) ? Math.trunc(number) : fallback;
}

/**
 * 저장된 값이 어떤 모양이든 완전한 설정으로 맞춘다. 모르는 값은 기본값으로 돌아간다.
 * `previous` 를 주면 비밀번호가 빠졌거나 빈 문자열일 때 기존 값을 유지한다 —
 * 화면은 비밀번호를 받지 못하므로 바꿀 때만 새 값을 보낸다.
 */
export function normalizeMailConfig(value: unknown, previous?: MailConfig): MailConfig {
  const defaults = defaultMailConfig();
  if (!isRecord(value)) return previous ?? defaults;

  const security = stringField(value.security, defaults.security).toLowerCase();
  let port = integerField(value.smtp_port, defaults.smtp_port);
  if (port <= 0) port = defaults.smtp_port;

  let password = previous?.password ?? '';
  if (typeof value.password === 'string' && value.password !== '') password = value.password;
  if (value.password_clear === true) password = '';

  return {
    enabled: value.enabled === true,
    smtp_host: stringField(value.smtp_host, ''),
    smtp_port: port,
    security: (MAIL_SECURITIES as readonly string[]).includes(security) ? security as MailSecurity : defaults.security,
    skip_tls_verify: value.skip_tls_verify === true,
    username: stringField(value.username, ''),
    password,
    from_address: stringField(value.from_address, ''),
    from_name: stringField(value.from_name, defaults.from_name),
    base_url: stringField(value.base_url, '').replace(/\/+$/, ''),
    timeout_seconds: integerField(value.timeout_seconds, defaults.timeout_seconds),
    recipients: stringField(value.recipients, ''),
    notify_activity_delayed: booleanField(value.notify_activity_delayed, true),
    notify_delay_cleared: booleanField(value.notify_delay_cleared, true),
    notify_task_completed: booleanField(value.notify_task_completed, true),
    notify_drill_completed: booleanField(value.notify_drill_completed, true),
  };
}

export function publicMailConfig(config: MailConfig): PublicMailConfig {
  const { password, ...rest } = config;
  return { ...rest, password_set: password !== '' };
}

/** 느슨한 주소 검사. 릴레이가 최종 판단하므로 `이름@호스트` 모양이면 통과시킨다. */
export function isEmailAddress(value: string) {
  return /^[^\s@<>,;"]+@[^\s@<>,;"]+\.[^\s@<>,;"]+$/.test(value) || /^[^\s@<>,;"]+@[^\s@<>,;".]+$/.test(value);
}

/** 쉼표·세미콜론·줄바꿈으로 나눈 주소 목록. 대소문자만 다른 중복은 하나로 본다. */
export function parseRecipients(raw: string): string[] {
  const seen = new Set<string>();
  const addresses: string[] = [];
  for (const part of raw.split(/[,;\n]/)) {
    const address = part.trim();
    if (!address) continue;
    const key = address.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    addresses.push(address);
  }
  return addresses;
}

/**
 * 저장 전 검사. 꺼져 있으면 값이 비어 있어도 저장할 수 있다 — 관리자가 조금씩 채우다
 * 켜기 때문이다. 켜면 릴레이 주소와 보내는 주소가 있어야 한다.
 */
export function validateMailConfig(config: MailConfig): MailValidationIssue[] {
  const issues: MailValidationIssue[] = [];

  if (config.smtp_port < 1 || config.smtp_port > 65535) {
    issues.push({ path: 'smtp_port', message: '1 이상 65535 이하의 포트 번호여야 합니다.' });
  }
  if (config.timeout_seconds < MIN_TIMEOUT_SECONDS || config.timeout_seconds > MAX_TIMEOUT_SECONDS) {
    issues.push({ path: 'timeout_seconds', message: `${MIN_TIMEOUT_SECONDS} 이상 ${MAX_TIMEOUT_SECONDS} 이하의 초여야 합니다.` });
  }
  if (config.from_address && !isEmailAddress(config.from_address)) {
    issues.push({ path: 'from_address', message: '보내는 주소는 이름@호스트 모양이어야 합니다.' });
  }
  if (config.base_url && !/^https?:\/\/[^\s/]+/i.test(config.base_url)) {
    issues.push({ path: 'base_url', message: 'http:// 또는 https:// 로 시작하는 주소여야 합니다.' });
  }
  if (config.password && !config.username) {
    issues.push({ path: 'username', message: '비밀번호를 쓰려면 사용자 이름도 필요합니다.' });
  }

  const recipients = parseRecipients(config.recipients);
  if (recipients.length > MAX_RECIPIENTS) {
    issues.push({ path: 'recipients', message: `받는 사람은 최대 ${MAX_RECIPIENTS}명까지 적을 수 있습니다.` });
  }
  for (const address of recipients) {
    if (!isEmailAddress(address)) {
      issues.push({ path: 'recipients', message: `"${address}" 는 이름@호스트 모양이 아닙니다.` });
    }
  }

  if (config.enabled) {
    if (!config.smtp_host) issues.push({ path: 'smtp_host', message: '메일을 켜려면 릴레이 주소가 필요합니다.' });
    if (!config.from_address) issues.push({ path: 'from_address', message: '메일을 켜려면 보내는 주소가 필요합니다.' });
  }

  return issues;
}

/**
 * 켜져 있어도 보낼 수 없는 이유. 없으면 null. 켠 채로 저장은 됐지만 호스트가 빠진 것 같은
 * 상태를 조용히 넘기지 않고 발송 기록에 이유로 남기기 위한 것이다.
 */
export function mailUnavailableReason(config: MailConfig): string | null {
  if (!config.enabled) return '메일 알림이 꺼져 있습니다.';
  if (!config.smtp_host) return '릴레이 주소(mail.smtp_host)가 비어 있습니다.';
  if (!config.from_address) return '보내는 주소(mail.from_address)가 비어 있습니다.';
  return null;
}

/** 이벤트 스위치. 스위치가 없는 이벤트(시험 발송)는 늘 보낸다. */
export function allowsEvent(config: MailConfig, event: MailEvent) {
  const key = (MAIL_EVENT_SWITCHES as Partial<Record<MailEvent, MailEventSwitch>>)[event];
  return key ? config[key] : true;
}
/**
 * 발송 서비스. 설정을 읽고, 받는 사람을 정하고, 시도마다 기록하고, 릴레이로 보낸다.
 *
 * 요청 경로에서는 notify 를 Next 의 after() 안에서 부른다 — 응답이 나간 뒤에 돌므로 릴레이가
 * 느리거나 죽어 있어도 상태 클릭 하나가 기다리지 않는다. 발송 실패는 그 요청의 실패가 아니다.
 * 전송 함수와 기록 함수는 바꿔 끼울 수 있어 테스트가 실제 릴레이 없이 돈다.
 */
import { randomUUID } from 'node:crypto';
import type { Activity } from '../types.ts';
import {
  mailUnavailableReason,
  parseRecipients,
  type MailConfig,
} from './config.ts';
import {
  composeNotification,
  detectMailChanges,
  renderBody,
  testNotification,
  type Notification,
} from './events.ts';
import { composeMessage } from './message.ts';
import { readMailConfig, recordDelivery, updateDelivery, type Delivery } from './store.ts';
import { sendMail, type SmtpEnvelope, type SmtpOptions } from './smtp.ts';

export interface MailServiceDeps {
  readConfig: () => Promise<MailConfig>;
  send: (options: SmtpOptions, envelope: SmtpEnvelope) => Promise<void>;
  record: (delivery: Delivery) => Promise<void>;
  update: (id: string, patch: Partial<Pick<Delivery, 'status' | 'attempts' | 'error_message'>>) => Promise<void>;
  now: () => Date;
  sleep: (ms: number) => Promise<void>;
}

export class MailUnavailableError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'MailUnavailableError';
  }
}

const RETRY_DELAY_MS = 2000;
const MAX_ERROR_LENGTH = 1000;

export function smtpOptionsFrom(config: MailConfig): SmtpOptions {
  const domain = config.from_address.split('@')[1] ?? '';
  return {
    host: config.smtp_host,
    port: config.smtp_port,
    // 465 는 처음부터 TLS 인 포트다. auto 인 채로 두면 평문 인사를 기다리다 시간 초과가 난다.
    security: config.security === 'auto' && config.smtp_port === 465 ? 'tls' : config.security,
    skipTlsVerify: config.skip_tls_verify,
    username: config.username,
    password: config.password,
    timeoutMs: config.timeout_seconds * 1000,
    heloName: domain || 'localhost',
  };
}

function errorText(error: unknown) {
  const text = error instanceof Error ? error.message : String(error);
  return text.length > MAX_ERROR_LENGTH ? text.slice(0, MAX_ERROR_LENGTH) : text;
}

export function createMailService(overrides: Partial<MailServiceDeps> = {}) {
  const deps: MailServiceDeps = {
    readConfig: readMailConfig,
    send: sendMail,
    record: recordDelivery,
    update: updateDelivery,
    now: () => new Date(),
    sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
    ...overrides,
  };

  function newDelivery(notification: Notification, recipient: string): Delivery {
    const moment = deps.now().toISOString();
    return {
      id: randomUUID(),
      event: notification.event,
      recipient,
      subject: notification.subject.slice(0, 300),
      status: 'queued',
      attempts: 0,
      error_message: '',
      created_at: moment,
      updated_at: moment,
    };
  }

  async function complete(delivery: Delivery, attempts: number, cause: unknown) {
    const patch = cause === undefined
      ? { status: 'sent' as const, attempts, error_message: '' }
      : { status: 'failed' as const, attempts, error_message: errorText(cause) };
    if (cause !== undefined) {
      // 비밀번호는 오류 문장에 들어가지 않는다(smtp.ts). 여기서도 설정을 통째로 찍지 않는다.
      console.warn(`메일 발송 실패 [${delivery.event}] → ${delivery.recipient}: ${patch.error_message}`);
    }
    await deps.update(delivery.id, patch).catch((error) => console.warn('메일 발송 기록을 갱신하지 못했습니다:', error));
  }

  /** 한 번 더 시도한다. 잠깐 연결을 거부하는 릴레이는 흔하고, 알림을 잃는 것이 2초 기다리는 것보다 나쁘다. */
  async function deliver(config: MailConfig, delivery: Delivery, envelope: SmtpEnvelope, retries: number) {
    let cause: unknown;
    let attempts = 0;
    for (attempts = 1; attempts <= retries + 1; attempts += 1) {
      try {
        await deps.send(smtpOptionsFrom(config), envelope);
        cause = undefined;
        break;
      } catch (error) {
        cause = error ?? new Error('알 수 없는 오류');
        if (attempts <= retries) await deps.sleep(RETRY_DELAY_MS);
      }
    }
    await complete(delivery, Math.min(attempts, retries + 1), cause);
    return cause;
  }

  function envelopeFor(config: MailConfig, notification: Notification, recipient: string): SmtpEnvelope {
    return {
      from: config.from_address,
      to: recipient,
      data: composeMessage({
        from: { name: config.from_name, address: config.from_address },
        to: recipient,
        subject: notification.subject,
        body: renderBody(notification, config),
      }, deps.now()),
    };
  }

  /** 켜져 있지만 보낼 수 없을 때, 기록에 이유를 남긴다. 조용히 넘기면 "안 왔다" 에 답할 수 없다. */
  async function recordUnavailable(notification: Notification, reason: string) {
    const delivery = { ...newDelivery(notification, '-'), status: 'failed' as const, error_message: reason };
    await deps.record(delivery).catch((error) => console.warn('메일 발송 기록을 남기지 못했습니다:', error));
  }

  return {
    config: () => deps.readConfig(),

    /**
     * 명부의 모두에게 한 통씩 보낸다. 절대 던지지 않는다 — 호출한 요청은 이미 끝났다.
     * 꺼져 있으면 아무 기록도 남기지 않는다(새로 설치한 곳은 달라지지 않는다).
     */
    async notify(notification: Notification): Promise<void> {
      let config: MailConfig;
      try {
        config = await deps.readConfig();
      } catch (error) {
        console.warn('메일 설정을 읽지 못해 알림을 보내지 않습니다:', error);
        return;
      }
      if (!config.enabled) return;

      const reason = mailUnavailableReason(config);
      if (reason) {
        await recordUnavailable(notification, reason);
        return;
      }
      const recipients = parseRecipients(config.recipients);
      if (recipients.length === 0) {
        await recordUnavailable(notification, '받는 사람(mail.recipients)이 비어 있습니다.');
        return;
      }

      for (const recipient of recipients) {
        const delivery = newDelivery(notification, recipient);
        try {
          await deps.record(delivery);
          await deliver(config, delivery, envelopeFor(config, notification, recipient), 1);
        } catch (error) {
          console.warn('메일 발송 기록을 남기지 못했습니다:', error);
        }
      }
    },

    /**
     * 시험 발송. 바로 보내고 결과를 돌려준다 — 관리 화면의 단추가 그 자리에서 답을 보여 준다.
     * 재시도하지 않는다(사람이 보고 있다).
     */
    async sendNow(notification: Notification, recipient: string): Promise<Delivery> {
      const config = await deps.readConfig();
      const reason = mailUnavailableReason(config);
      if (reason) throw new MailUnavailableError(reason);

      const delivery = newDelivery(notification, recipient);
      await deps.record(delivery);
      const cause = await deliver(config, delivery, envelopeFor(config, notification, recipient), 0);
      if (cause !== undefined) {
        throw cause instanceof Error ? cause : new Error(errorText(cause));
      }
      return { ...delivery, status: 'sent', attempts: 1, updated_at: deps.now().toISOString() };
    },
  };
}

export type MailService = ReturnType<typeof createMailService>;

const SERVICE_KEY = '__cutoverMailService';

/** 라우트마다 모듈이 따로 묶여도 하나의 서비스를 쓴다. */
export function getMailService(): MailService {
  const store = globalThis as typeof globalThis & { [SERVICE_KEY]?: MailService };
  if (!store[SERVICE_KEY]) store[SERVICE_KEY] = createMailService();
  return store[SERVICE_KEY];
}

/**
 * 상황판 저장 뒤에 부른다. 저장 전후를 비교해 메일감을 고르고, 있으면 한 통으로 묶어 보낸다.
 * after() 안에서 돌도록 만들어졌으므로 무엇도 던지지 않는다.
 */
export async function notifyActivityChanges(
  before: Activity[],
  after: Activity[],
  dashboardTitle: string,
  service: MailService = getMailService(),
): Promise<void> {
  try {
    const changes = detectMailChanges(before, after);
    if (changes.length === 0) return;
    // 스위치는 설정을 읽어야 알 수 있다. 꺼져 있으면 여기서 읽는 것이 유일한 비용이다.
    const config = await service.config();
    if (!config.enabled) return;
    const notification = composeNotification(changes, config, dashboardTitle);
    if (!notification) return;
    await service.notify(notification);
  } catch (error) {
    console.warn('메일 알림 처리 중 오류가 났지만 상황판 저장에는 영향이 없습니다:', error);
  }
}

export { testNotification };
/**
 * 상황판 변경에서 메일감을 골라내는 순수 로직.
 *
 * 관리자 콘솔의 한 번의 조작(상태 클릭)은 연동 규칙 때문에 여러 액티비티를 한꺼번에 바꾼다 —
 * 부모를 완료로 두면 자식이 모두 완료가 되고, 마지막 자식이 완료되면 부모도 완료가 된다.
 * 그래서 저장 전후를 비교해 바뀐 것을 모으고, 한 통으로 묶는다. 한 번 눌렀는데 메일이
 * 다섯 통 오면 사람들은 규칙을 만들어 통째로 버린다.
 */
import type { Activity } from '../types.ts';
import { allowsEvent, type MailConfig, type MailEvent } from './config.ts';

export interface ActivityChange {
  event: Exclude<MailEvent, 'test'>;
  activity: Activity;
  /** 바뀌기 전 상태. 지연 해소는 어디서 왔는지가 문장에 들어간다. */
  previousStatus: Activity['status'];
}

export interface DrillChange {
  event: 'drill.completed';
}

export type MailChange = ActivityChange | DrillChange;

/** 한 통의 메일. 본문은 발송 기록에 담지 않는다 — 제목과 수신자면 충분하다. */
export interface Notification {
  event: MailEvent;
  subject: string;
  lines: string[];
  /** base_url 뒤에 붙는 경로. 메일 속 링크가 가리킬 화면. */
  link: string;
}

/** 우선순위가 높은 것이 제목이 된다. 지연은 완료보다 급하다. */
const EVENT_PRIORITY: Record<Exclude<MailEvent, 'test'>, number> = {
  'activity.delayed': 0,
  'drill.completed': 1,
  'task.completed': 2,
  'activity.delay_cleared': 3,
};

const EVENT_LABEL: Record<Exclude<MailEvent, 'test'>, string> = {
  'activity.delayed': '지연',
  'activity.delay_cleared': '지연 해소',
  'task.completed': '작업 완료',
  'drill.completed': '훈련 완료',
};

function isRoot(activity: Activity) {
  return activity.parentId === null || activity.level === 1;
}

/** 저장 전후의 목록을 비교해 메일감이 되는 변화만 돌려준다. 새로 생기거나 지워진 항목은 세지 않는다. */
export function detectMailChanges(before: Activity[], after: Activity[]): MailChange[] {
  const previousById = new Map(before.map((activity) => [activity.id, activity]));
  const changes: MailChange[] = [];

  for (const activity of after) {
    const previous = previousById.get(activity.id);
    if (!previous || previous.status === activity.status) continue;

    if (activity.status === '지연') {
      changes.push({ event: 'activity.delayed', activity, previousStatus: previous.status });
      continue;
    }
    if (previous.status === '지연' && activity.status !== '대기') {
      changes.push({ event: 'activity.delay_cleared', activity, previousStatus: previous.status });
    }
    if (isRoot(activity) && activity.status === '완료') {
      changes.push({ event: 'task.completed', activity, previousStatus: previous.status });
    }
  }

  const rootsAfter = after.filter(isRoot);
  const rootsBefore = before.filter(isRoot);
  const allDone = (roots: Activity[]) => roots.length > 0 && roots.every((activity) => activity.status === '완료');
  if (allDone(rootsAfter) && !allDone(rootsBefore)) {
    changes.push({ event: 'drill.completed' });
  }

  return changes;
}

function describe(change: ActivityChange) {
  const { activity } = change;
  const where = activity.time && activity.time !== '미정' ? ` (${activity.time})` : '';
  switch (change.event) {
    case 'activity.delayed':
      return `[지연] ${activity.title}${where} — ${change.previousStatus} → 지연`;
    case 'activity.delay_cleared':
      return `[지연 해소] ${activity.title}${where} — 지연 → ${activity.status}`;
    case 'task.completed':
      return `[완료] ${activity.title}${where}`;
    default:
      return activity.title;
  }
}

/**
 * 변화 목록을 한 통으로 묶는다. 스위치가 꺼진 종류는 빠지고, 남은 것이 없으면 null.
 * 제목은 가장 급한 변화 하나로 짓고 나머지는 "외 n건" 으로 접는다.
 */
export function composeNotification(
  changes: MailChange[],
  config: MailConfig,
  dashboardTitle: string,
): Notification | null {
  const allowed = changes.filter((change) => allowsEvent(config, change.event));
  if (allowed.length === 0) return null;

  const sorted = [...allowed].sort((left, right) => EVENT_PRIORITY[left.event] - EVENT_PRIORITY[right.event]);
  const primary = sorted[0];
  const others = sorted.length - 1;
  const suffix = others > 0 ? ` 외 ${others}건` : '';

  const headline = primary.event === 'drill.completed'
    ? '모든 작업이 완료되었습니다'
    : `${EVENT_LABEL[primary.event]}: ${primary.activity.title}`;

  const lines: string[] = [`${dashboardTitle} 상황판에서 다음 변화가 있었습니다.`, ''];
  for (const change of sorted) {
    lines.push(change.event === 'drill.completed'
      ? '[훈련 완료] 모든 최상위 작업이 완료 상태가 되었습니다.'
      : `${describe(change)}`);
  }

  return {
    event: primary.event,
    subject: `[${dashboardTitle}] ${headline}${suffix}`,
    lines,
    link: '/pc',
  };
}

/** 관리 화면의 시험 발송. 이 메일이 오면 릴레이 설정이 맞는 것이다. */
export function testNotification(dashboardTitle: string): Notification {
  return {
    event: 'test',
    subject: `[${dashboardTitle}] SMTP 발송 테스트`,
    lines: [
      '관리자 화면에서 보낸 테스트 메일입니다.',
      '이 메일을 받았다면 SMTP 릴레이 설정이 정상입니다.',
    ],
    link: '/admin',
  };
}

/** 본문 문장에 링크와 꼬리말을 붙인다. 링크는 base_url 이 있을 때만 들어간다. */
export function renderBody(notification: Notification, config: MailConfig) {
  const lines = [...notification.lines];
  if (config.base_url && notification.link) {
    lines.push('', `바로 열기: ${config.base_url}${notification.link.startsWith('/') ? '' : '/'}${notification.link}`);
  }
  lines.push('', '—', '이 메일은 Cutover 상황판의 메일 알림 설정에 따라 자동으로 발송되었습니다.');
  return lines.join('\n');
}

