import { extractOrigin, policySources, sourceAllows, type TrackingConfig } from './core.ts';

/**
 * 차단된 요청은 페이지마다 반복되므로 횟수가 아니라 서로 다른 출처가 중요하다.
 * 100개쯤 담는 고리 버퍼면 스니펫을 고치기에 충분하다.
 */
export const MAX_VIOLATIONS = 100;

export interface CspViolation {
  origin: string;
  directive: string;
  page: string;
  count: number;
  firstSeen: string;
  lastSeen: string;
  /** 현재 설정이 이미 허용하는 출처. 고친 스니펫이 계속 잔소리하지 않게 한다. */
  allowed: boolean;
}

interface StoredViolation extends Omit<CspViolation, 'allowed'> {
  lastSeenMs: number;
}

/**
 * 메모리에만 둔다. 신고는 스니펫을 붙이는 사람을 위한 실시간 진단이지 감사 기록이 아니다.
 * Next 는 라우트마다 모듈을 따로 묶을 수 있어 globalThis 에 걸어 두어야 신고를 받은 라우트와
 * 목록을 보여 주는 라우트가 같은 버퍼를 본다.
 */
export class ViolationRecorder {
  private violations = new Map<string, StoredViolation>();
  private now: () => number;

  constructor(now: () => number = Date.now) {
    this.now = now;
  }

  /** http 출처가 아닌 것(브라우저 확장, data: URL)은 허용할 수도 없고 쓸모도 없어 버린다. */
  record(blockedUri: string, directive: string, page: string) {
    const origin = extractOrigin(blockedUri);
    if (!origin) return;

    let normalizedDirective = directive.trim().toLowerCase().split(' ')[0];
    if (!normalizedDirective) normalizedDirective = 'connect-src';

    const key = `${normalizedDirective} ${origin}`;
    const moment = this.now();
    const existing = this.violations.get(key);
    if (existing) {
      existing.count += 1;
      existing.lastSeenMs = moment;
      existing.lastSeen = new Date(moment).toISOString();
      existing.page = page;
      return;
    }

    if (this.violations.size >= MAX_VIOLATIONS) this.evictOldest();
    this.violations.set(key, {
      origin,
      directive: normalizedDirective,
      page,
      count: 1,
      firstSeen: new Date(moment).toISOString(),
      lastSeen: new Date(moment).toISOString(),
      lastSeenMs: moment,
    });
  }

  private evictOldest() {
    let oldestKey: string | undefined;
    let oldest = Number.POSITIVE_INFINITY;
    for (const [key, violation] of this.violations) {
      if (violation.lastSeenMs < oldest) {
        oldestKey = key;
        oldest = violation.lastSeenMs;
      }
    }
    if (oldestKey !== undefined) this.violations.delete(oldestKey);
  }

  /** 최근 것부터. 현재 설정이 허용하는 출처는 표시해 둔다. */
  list(config: TrackingConfig): CspViolation[] {
    const sources = policySources(config);
    const patterns = [...sources.scripts, ...sources.connects, ...sources.images];

    return [...this.violations.values()]
      .sort((first, second) => second.lastSeenMs - first.lastSeenMs || first.origin.localeCompare(second.origin))
      .map((violation) => ({
        origin: violation.origin,
        directive: violation.directive,
        page: violation.page,
        count: violation.count,
        firstSeen: violation.firstSeen,
        lastSeen: violation.lastSeen,
        allowed: patterns.some((pattern) => sourceAllows(pattern, violation.origin)),
      }));
  }

  get size() {
    return this.violations.size;
  }

  /** 스니펫을 고친 뒤 아직 막히는 것이 있는지 다시 보려고 비운다. */
  forget() {
    this.violations.clear();
  }
}

const RECORDER_KEY = Symbol.for('cutover.tracking.violations');

export function getViolationRecorder(): ViolationRecorder {
  const store = globalThis as typeof globalThis & { [RECORDER_KEY]?: ViolationRecorder };
  if (!store[RECORDER_KEY]) store[RECORDER_KEY] = new ViolationRecorder();
  return store[RECORDER_KEY];
}
/**
 * 방문 추적 스크립트 체계의 순수 로직.
 *
 * 이 앱의 콘텐츠 보안 정책(CSP)은 스크립트를 앱 오리진과 요청별 nonce 로만 허용한다.
 * 그래서 추적 스니펫을 그냥 붙여 넣으면 브라우저가 조용히 차단한다. 이 모듈은
 * 그 답의 두 반쪽 — 삽입할 <script> 목록과 정책에 더할 출처 — 을 설정에서 만든다.
 * 파일 입출력이나 Next 의존성이 없어 node --test 로 그대로 검증한다.
 */

export const TRACKING_PROVIDERS = ['none', 'momento', 'ga4', 'gtm', 'matomo', 'custom'] as const;
export type TrackingProvider = (typeof TRACKING_PROVIDERS)[number];

export const TRACKING_PLACEMENTS = ['head', 'body'] as const;
export type TrackingPlacement = (typeof TRACKING_PLACEMENTS)[number];

export const MAX_SNIPPET_BYTES = 8 * 1024;
export const MAX_ALLOWED_HOSTS = 50;

/** Momento 같은 오리진 프록시 경로. 앱이 이 아래를 수집기로 넘긴다. */
export const MOMENTO_PROXY_PATH = '/momento';
/** 브라우저가 차단한 요청을 신고하는 경로. 추적이 켜진 동안에만 정책에 들어간다. */
export const CSP_REPORT_PATH = '/api/csp-report';

export interface TrackingConfig {
  enabled: boolean;
  provider: TrackingProvider;
  momento_url: string;
  momento_site_id: string;
  momento_environment: string;
  /** 켜면 /momento/* 를 통해 수집기로 넘겨 외부 출처가 정책에 등장하지 않는다. */
  momento_proxy: boolean;
  measurement_id: string;
  matomo_url: string;
  matomo_site_id: string;
  custom_snippet: string;
  allowed_hosts: string;
  include_admin: boolean;
  placement: TrackingPlacement;
}

export interface TrackingValidationIssue {
  path: string;
  message: string;
}

export class TrackingValidationError extends Error {
  issues: TrackingValidationIssue[];

  constructor(issues: TrackingValidationIssue[]) {
    super('추적 설정이 올바르지 않습니다.');
    this.name = 'TrackingValidationError';
    this.issues = issues;
  }
}

/** 삽입할 <script> 하나. 문자열이 아니라 구조로 두어 React 가 속성을 이스케이프한다. */
export interface SnippetScript {
  src?: string;
  inline?: string;
  attributes: Record<string, string | true>;
}

export interface PolicySources {
  scripts: string[];
  connects: string[];
  images: string[];
}

export function defaultTrackingConfig(): TrackingConfig {
  return {
    enabled: false,
    provider: 'none',
    momento_url: '',
    momento_site_id: '',
    momento_environment: 'prd',
    momento_proxy: true,
    measurement_id: '',
    matomo_url: '',
    matomo_site_id: '',
    custom_snippet: '',
    allowed_hosts: '',
    include_admin: false,
    placement: 'head',
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function stringField(value: unknown, fallback: string) {
  return typeof value === 'string' ? value.trim() : fallback;
}

/** 저장된 값이 어떤 모양이든 완전한 설정으로 맞춘다. 모르는 값은 기본값으로 돌아간다. */
export function normalizeTrackingConfig(value: unknown): TrackingConfig {
  const defaults = defaultTrackingConfig();
  if (!isRecord(value)) return defaults;

  const provider = stringField(value.provider, defaults.provider).toLowerCase();
  const placement = stringField(value.placement, defaults.placement).toLowerCase();

  return {
    enabled: value.enabled === true,
    provider: (TRACKING_PROVIDERS as readonly string[]).includes(provider) ? provider as TrackingProvider : 'none',
    momento_url: stringField(value.momento_url, ''),
    momento_site_id: stringField(value.momento_site_id, ''),
    momento_environment: stringField(value.momento_environment, defaults.momento_environment) || defaults.momento_environment,
    momento_proxy: value.momento_proxy !== false,
    measurement_id: stringField(value.measurement_id, ''),
    matomo_url: stringField(value.matomo_url, ''),
    matomo_site_id: stringField(value.matomo_site_id, ''),
    custom_snippet: typeof value.custom_snippet === 'string' ? value.custom_snippet.trim() : '',
    allowed_hosts: stringField(value.allowed_hosts, ''),
    include_admin: value.include_admin === true,
    placement: (TRACKING_PLACEMENTS as readonly string[]).includes(placement) ? placement as TrackingPlacement : 'head',
  };
}

function originOf(raw: string): string {
  const trimmed = raw.trim();
  if (!/^https?:\/\//i.test(trimmed)) return '';
  try {
    const parsed = new URL(trimmed);
    return parsed.host ? parsed.origin : '';
  } catch {
    return '';
  }
}

/** 관리자가 손으로 적는 허용 출처. 정책 헤더에 그대로 들어가므로 모양을 엄격히 본다. */
const ALLOWED_HOST_PATTERN = /^https?:\/\/(\*\.)?[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*(:\d{1,5})?$/;

export function splitAllowedHosts(allowedHosts: string): string[] {
  return allowedHosts
    .split(/[,\s]+/)
    .map((host) => host.trim().replace(/\/+$/, ''))
    .filter((host) => host.length > 0);
}

/** 허용 목록에 출처를 더한다. 이미 있으면 그대로 둔다. */
export function addAllowedHost(existing: string, origin: string): string {
  const candidate = origin.trim().replace(/\/+$/, '');
  if (!candidate) return existing;

  const hosts = splitAllowedHosts(existing);
  if (hosts.some((host) => host.toLowerCase() === candidate.toLowerCase())) return existing;
  return [...hosts, candidate].join(', ');
}

/** 선택한 provider 에 필요한 값이 빠졌는지 본다. 꺼져 있으면 무엇이든 저장할 수 있다. */
export function validateTrackingConfig(config: TrackingConfig): TrackingValidationIssue[] {
  const issues: TrackingValidationIssue[] = [];

  if (new TextEncoder().encode(config.custom_snippet).length > MAX_SNIPPET_BYTES) {
    issues.push({ path: 'custom_snippet', message: `추적 코드는 ${MAX_SNIPPET_BYTES / 1024}KB 를 넘을 수 없습니다.` });
  }

  const hosts = splitAllowedHosts(config.allowed_hosts);
  if (hosts.length > MAX_ALLOWED_HOSTS) {
    issues.push({ path: 'allowed_hosts', message: `허용 출처는 최대 ${MAX_ALLOWED_HOSTS}개까지 적을 수 있습니다.` });
  }
  for (const host of hosts) {
    if (!ALLOWED_HOST_PATTERN.test(host)) {
      issues.push({ path: 'allowed_hosts', message: `"${host}" 는 https://host[:port] 또는 https://*.domain 모양이어야 합니다.` });
    }
  }

  if (config.momento_url && !originOf(config.momento_url)) {
    issues.push({ path: 'momento_url', message: 'momento_url 은 http(s) 로 시작하는 주소여야 합니다.' });
  }
  if (config.matomo_url && !originOf(config.matomo_url)) {
    issues.push({ path: 'matomo_url', message: 'matomo_url 은 http(s) 로 시작하는 주소여야 합니다.' });
  }
  if (!/^[A-Za-z0-9._-]*$/.test(config.momento_environment)) {
    issues.push({ path: 'momento_environment', message: 'momento_environment 는 영문·숫자·._- 만 쓸 수 있습니다.' });
  }

  if (!config.enabled) return issues;

  switch (config.provider) {
    case 'momento':
      if (!config.momento_url || !config.momento_site_id) {
        issues.push({ path: 'momento_url', message: 'Momento 는 momento_url 과 momento_site_id 가 필요합니다.' });
      }
      break;
    case 'ga4':
    case 'gtm':
      if (!config.measurement_id) {
        issues.push({ path: 'measurement_id', message: `${config.provider.toUpperCase()} 는 measurement_id 가 필요합니다.` });
      } else if (!/^[A-Za-z0-9-]+$/.test(config.measurement_id)) {
        issues.push({ path: 'measurement_id', message: 'measurement_id 는 영문·숫자·하이픈만 쓸 수 있습니다.' });
      }
      break;
    case 'matomo':
      if (!config.matomo_url || !config.matomo_site_id) {
        issues.push({ path: 'matomo_url', message: 'Matomo 는 matomo_url 과 matomo_site_id 가 필요합니다.' });
      }
      break;
    case 'custom':
      if (!config.custom_snippet) {
        issues.push({ path: 'custom_snippet', message: '직접 입력 방식은 추적 코드를 붙여 넣어야 합니다.' });
      } else if (parseSnippetScripts(config.custom_snippet).length === 0) {
        issues.push({ path: 'custom_snippet', message: '추적 코드에 <script> 태그가 없습니다. <script> 태그만 삽입됩니다.' });
      }
      break;
    default:
      break;
  }

  return issues;
}

/** 관리 화면(/admin) 처럼 방문자 데이터가 아닌 경로. include_admin 이 켜져야 붙는다. */
export function isAdminPath(pathname: string) {
  return pathname === '/admin' || pathname.startsWith('/admin/');
}

/** 화면이 아닌 경로. 스니펫도 붙지 않고 정책도 더 좁다. */
export function isNonPagePath(pathname: string) {
  return pathname.startsWith('/api/')
    || pathname === MOMENTO_PROXY_PATH
    || pathname.startsWith(`${MOMENTO_PROXY_PATH}/`)
    || pathname.startsWith('/_next/');
}

/** 이 경로의 페이지에 스니펫을 붙여야 하는가. */
export function isTrackingActive(config: TrackingConfig, pathname: string) {
  if (!config.enabled || config.provider === 'none') return false;
  if (isNonPagePath(pathname)) return false;
  if (!config.include_admin && isAdminPath(pathname)) return false;
  return renderSnippetScripts(config).length > 0;
}

function momentoBase(config: TrackingConfig) {
  return config.momento_url.replace(/\/+$/, '');
}

/** provider 별 <script> 목록. nonce 는 렌더링할 때 모든 태그에 붙는다. */
export function renderSnippetScripts(config: TrackingConfig): SnippetScript[] {
