function unauthorizedResponse() {
  return NextResponse.json(
    { error: '관리자 인증이 만료되었습니다. 다시 로그인해 주세요.', code: 'UNAUTHORIZED' },
    { status: 401 },
  );
}

export async function GET() {
  try {
    const data = await readActivityData();
    return NextResponse.json(data, {
      headers: { 'Cache-Control': 'no-store' },
    });
  } catch (error) {
    console.error('GET /api/activities failed:', error);
    return NextResponse.json(
      {
        activities: [],
        dashboardTitle: DEFAULT_DASHBOARD_TITLE,
        visitorCount: 0,
        lastUpdated: new Date().toISOString(),
        error: '저장된 상황판 데이터를 읽지 못했습니다.',
      },
      { status: 500 },
    );
  }
}

export async function PUT(request: NextRequest) {
  if (!isAdminRequest(request)) return unauthorizedResponse();

  try {
    const body: unknown = await request.json();
    if (!isRecord(body)) {
      return NextResponse.json({ error: '요청 본문은 JSON 객체여야 합니다.' }, { status: 400 });
    }

    const currentData = await readActivityData();
    let updated: Activity[] = currentData.activities;

    if (Array.isArray(body.activities)) {
      updated = body.activities as Activity[];
    } else if (body.action === 'add' && (typeof body.parentId === 'string' || body.parentId === null)) {
      updated = addActivity(updated, body.parentId);
    } else if (body.action === 'delete' && typeof body.targetId === 'string') {
      updated = deleteActivity(updated, body.targetId);
    } else if (
      body.action === 'move'
      && typeof body.targetId === 'string'
      && (body.direction === 'up' || body.direction === 'down')
    ) {
      updated = moveActivity(updated, body.targetId, body.direction);
    } else if (typeof body.targetId === 'string' && typeof body.newStatus === 'string') {
      updated = updated.map((activity) => (
        activity.id === body.targetId ? { ...activity, status: body.newStatus as Activity['status'] } : activity
      ));
    }

    const dashboardTitle = body.dashboardTitle === undefined
      ? currentData.dashboardTitle
      : body.dashboardTitle;
    const validated = validateActivityImport({ activities: updated, dashboardTitle });
    const newData = {
      activities: validated.activities,
      dashboardTitle: validated.dashboardTitle ?? currentData.dashboardTitle,
      lastUpdated: new Date().toISOString(),
      visitorCount: currentData.visitorCount,
    };

    await writeActivityData(newData);
    // 메일은 응답이 나간 뒤 배경에서 보낸다. 릴레이가 죽어 있어도 이 요청은 여기서 끝난다.
    after(() => notifyActivityChanges(currentData.activities, newData.activities, newData.dashboardTitle));
    return NextResponse.json(newData);
  } catch (error) {
    if (error instanceof ActivityImportValidationError) {
      return NextResponse.json(
        { error: error.message, code: 'INVALID_DATA', details: error.issues },
        { status: 400 },
      );
    }

    if (error instanceof SyntaxError) {
      return NextResponse.json({ error: '요청 JSON 문법이 올바르지 않습니다.' }, { status: 400 });
    }

    console.error('PUT /api/activities failed:', error);
    return NextResponse.json({ error: '상황판 데이터를 저장하지 못했습니다.' }, { status: 500 });
  }
}
import type { Activity } from './types.ts';

export function buildTree(activities: Activity[]): Activity[] {
  const map = new Map<string, Activity>();
  const roots: Activity[] = [];

  activities.forEach(act => {
    map.set(act.id, { ...act, children: [] });
  });

  activities.forEach(act => {
    const node = map.get(act.id)!;
    if (act.parentId) {
      const parent = map.get(act.parentId);
      if (parent) parent.children!.push(node);
    } else {
      roots.push(node);
    }
  });

  return roots;
}

export function moveActivity(activities: Activity[], targetId: string, direction: 'up' | 'down'): Activity[] {
  const newActivities = [...activities];
  const targetIndex = newActivities.findIndex(a => a.id === targetId);
  if (targetIndex === -1) return newActivities;

  const target = newActivities[targetIndex];
  const siblings = newActivities.filter(a => a.parentId === target.parentId);
  const siblingIds = siblings.map(s => s.id);
  const currentIndex = siblingIds.indexOf(targetId);

  if (direction === 'up' && currentIndex > 0) {
    const prevId = siblingIds[currentIndex - 1];
    const prevIndex = newActivities.findIndex(a => a.id === prevId);
    [newActivities[targetIndex], newActivities[prevIndex]] = [newActivities[prevIndex], newActivities[targetIndex]];
  } else if (direction === 'down' && currentIndex < siblingIds.length - 1) {
    const nextId = siblingIds[currentIndex + 1];
    const nextIndex = newActivities.findIndex(a => a.id === nextId);
    [newActivities[targetIndex], newActivities[nextIndex]] = [newActivities[nextIndex], newActivities[targetIndex]];
  }

  return newActivities;
}

export function addActivity(activities: Activity[], parentId: string | null): Activity[] {
  const newActivities = [...activities];
  const newId = parentId ? `${parentId}-${Date.now()}` : `${Date.now()}`;

  const newActivity: Activity = {
    id: newId,
    parentId: parentId || null,
    level: parentId ? (newActivities.find(a => a.id === parentId)?.level || 0) + 1 : 1,
    time: "미정",
    title: "새 액티비티",
    status: "대기"
  };

  newActivities.push(newActivity);
  return newActivities;
}

/**
 * rootId 와 그 아래 모든 하위(parentId 관계)의 id 를 모은다.
 * id 는 업로드한 activity.json 에서 아무 문자열이나 될 수 있으므로 `부모-번호` 접두사에 기대지 않는다.
 * parentId 가 순환하는 데이터가 들어와도 visited 로 끝난다.
 */
export function collectDescendantIds(activities: Activity[], rootId: string): Set<string> {
  const childrenByParent = new Map<string, string[]>();
  activities.forEach(act => {
    if (act.parentId === null || act.parentId === undefined) return;
    const siblings = childrenByParent.get(act.parentId);
    if (siblings) siblings.push(act.id);
    else childrenByParent.set(act.parentId, [act.id]);
  });

  const visited = new Set<string>([rootId]);
  const queue = [rootId];
  while (queue.length > 0) {
    const current = queue.shift()!;
    for (const childId of childrenByParent.get(current) ?? []) {
      if (visited.has(childId)) continue;
      visited.add(childId);
      queue.push(childId);
    }
  }
  return visited;
}

export function deleteActivity(activities: Activity[], targetId: string): Activity[] {
  const removed = collectDescendantIds(activities, targetId);
  return activities.filter(a => !removed.has(a.id));
}

