export function renderSnippetScripts(config: TrackingConfig): SnippetScript[] {
  switch (config.provider) {
    case 'momento': {
      const base = momentoBase(config);
      const siteId = config.momento_site_id;
      if (!base || !siteId) return [];
      const attributes: Record<string, string | true> = {
        async: true,
        'data-site-id': siteId,
        'data-environment': config.momento_environment || 'prd',
        'data-contract-version': '1',
      };
      if (config.momento_proxy) {
        attributes['data-endpoint'] = MOMENTO_PROXY_PATH;
        return [{ src: `${MOMENTO_PROXY_PATH}/tracker.js`, attributes }];
      }
      return [{ src: `${base}/tracker.js`, attributes }];
    }
    case 'ga4': {
      const id = config.measurement_id;
      if (!id) return [];
      return [
        { src: `https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(id)}`, attributes: { async: true } },
        {
          inline: `window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}gtag('js',new Date());gtag('config',${JSON.stringify(id)});`,
          attributes: {},
        },
      ];
    }
    case 'gtm': {
      const id = config.measurement_id;
      if (!id) return [];
      return [{
        inline: `(function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':new Date().getTime(),event:'gtm.js'});var f=d.getElementsByTagName(s)[0],j=d.createElement(s),dl=l!='dataLayer'?'&l='+l:'';j.async=true;j.src='https://www.googletagmanager.com/gtm.js?id='+i+dl;f.parentNode.insertBefore(j,f);})(window,document,'script','dataLayer',${JSON.stringify(id)});`,
        attributes: {},
      }];
    }
    case 'matomo': {
      const base = config.matomo_url.replace(/\/+$/, '');
      const siteId = config.matomo_site_id;
      if (!base || !siteId) return [];
      return [{
        inline: `var _paq=window._paq=window._paq||[];_paq.push(['trackPageView']);_paq.push(['enableLinkTracking']);(function(){var u=${JSON.stringify(`${base}/`)};_paq.push(['setTrackerUrl',u+'matomo.php']);_paq.push(['setSiteId',${JSON.stringify(siteId)}]);var d=document,g=d.createElement('script'),s=d.getElementsByTagName('script')[0];g.async=true;g.src=u+'matomo.js';s.parentNode.insertBefore(g,s);})();`,
        attributes: {},
      }];
    }
    case 'custom':
      return parseSnippetScripts(config.custom_snippet);
    default:
      return [];
  }
}

const SCRIPT_TAG_PATTERN = /<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi;
const ATTRIBUTE_PATTERN = /([^\s"'<>\/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'<>`]+)))?/g;

/**
 * 붙여 넣은 스니펫에서 <script> 태그만 뽑아 구조로 바꾼다. 그 밖의 마크업(noscript 등)은
 * 버린다 — 정책이 막는 것은 스크립트이고, 그것만 nonce 를 달아 다시 그릴 수 있다.
 * on* 속성과 기존 nonce 는 버린다. 인라인 핸들러는 어차피 정책에 막히고 nonce 는 요청마다 새로 단다.
 */
export function parseSnippetScripts(snippet: string): SnippetScript[] {
  const scripts: SnippetScript[] = [];
  for (const match of snippet.matchAll(SCRIPT_TAG_PATTERN)) {
    const attributes: Record<string, string | true> = {};
    let src: string | undefined;
    for (const attribute of match[1].matchAll(ATTRIBUTE_PATTERN)) {
      const name = attribute[1].toLowerCase();
      const value = attribute[2] ?? attribute[3] ?? attribute[4];
      if (name.startsWith('on') || name === 'nonce') continue;
      if (name === 'src') {
        src = value?.trim() || undefined;
        continue;
      }
      attributes[name] = value === undefined ? true : value;
    }
    const inline = match[2].trim();
    if (!src && !inline) continue;
    scripts.push(src ? { src, attributes } : { inline, attributes });
  }
  return scripts;
}

function escapeAttribute(value: string) {
  return value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

/**
 * <script> 목록을 nonce 를 달아 HTML 문자열로 만든다. body 끝에 넣을 때 쓴다 — React 는
 * async 외부 스크립트 요소를 head 로 끌어올리므로, 관리자가 고른 자리를 지키려면 문자열로 심어야 한다.
 */
export function serializeSnippetScripts(scripts: SnippetScript[], nonce: string) {
  return scripts.map((script) => {
    const attributes = [`nonce="${escapeAttribute(nonce)}"`, 'data-tracking-snippet=""'];
    if (script.src) attributes.push(`src="${escapeAttribute(script.src)}"`);
    for (const [name, value] of Object.entries(script.attributes)) {
      if (!/^[a-z][a-z0-9-]*$/.test(name)) continue;
      attributes.push(value === true ? name : `${name}="${escapeAttribute(value)}"`);
    }
    const inline = (script.inline ?? '').replace(/<\/(script)/gi, '<\\/$1');
    return `<script ${attributes.join(' ')}>${inline}</script>`;
  }).join('\n');
}

const URL_BOUNDARY = /["'`<>\s),;\\+]/;

/**
 * 스니펫 문자열에 적힌 모든 http(s) 출처. 추적 도구는 자기 주소를 로더 안에 적어 두므로
 * 여기서 읽으면 관리자가 정책 오류를 호스트 이름으로 번역해 손으로 넣을 필요가 없다.
 */
export function snippetOrigins(snippet: string): string[] {
  const origins: string[] = [];
  const seen = new Set<string>();
  const lower = snippet.toLowerCase();
  let index = 0;
  while (index < snippet.length) {
    const start = lower.indexOf('http', index);
    if (start < 0) break;
    let end = start;
    while (end < snippet.length && !URL_BOUNDARY.test(snippet[end])) end += 1;
    index = end > start ? end : start + 4;
    const origin = originOf(snippet.slice(start, end));
    if (!origin || seen.has(origin)) continue;
    seen.add(origin);
    origins.push(origin);
  }
  return origins;
}

/** 스니펫이 필요로 하는 추가 출처. provider 가 정해진 경우는 정책 지식 없이도 맞게 나온다. */
export function policySources(config: TrackingConfig): PolicySources {
  const sources: PolicySources = { scripts: [], connects: [], images: [] };
  const addEverywhere = (origin: string) => {
    for (const group of [sources.scripts, sources.connects, sources.images]) {
      if (!group.includes(origin)) group.push(origin);
    }
  };

  switch (config.provider) {
    case 'momento': {
      const origin = originOf(config.momento_url);
      // 같은 오리진 프록시를 쓰면 외부 출처가 정책에 아예 등장하지 않는다.
      if (origin && !config.momento_proxy) addEverywhere(origin);
      break;
    }
    case 'ga4':
    case 'gtm':
      sources.scripts.push('https://www.googletagmanager.com');
      sources.connects.push('https://www.google-analytics.com', 'https://analytics.google.com', 'https://*.google-analytics.com');
      sources.images.push('https://www.google-analytics.com', 'https://www.googletagmanager.com');
      break;
    case 'matomo': {
      const origin = originOf(config.matomo_url);
      if (origin) addEverywhere(origin);
      break;
    }
    case 'custom':
      for (const origin of snippetOrigins(config.custom_snippet)) addEverywhere(origin);
      break;
    default:
      break;
  }

  for (const host of splitAllowedHosts(config.allowed_hosts)) {
    if (ALLOWED_HOST_PATTERN.test(host)) addEverywhere(host);
  }

  return sources;
}

/** 정책 항목(https://*.example.com 포함)이 이 출처를 허용하는가. */
export function sourceAllows(pattern: string, origin: string) {
  const normalizedPattern = pattern.toLowerCase().replace(/\/+$/, '');
  const normalizedOrigin = origin.toLowerCase().replace(/\/+$/, '');
  if (normalizedPattern === normalizedOrigin) return true;

  const star = normalizedPattern.indexOf('*.');
  if (star < 0) return false;
  const scheme = normalizedPattern.slice(0, star);
  const suffix = normalizedPattern.slice(star + 1);
  return normalizedOrigin.startsWith(scheme) && normalizedOrigin.endsWith(suffix);
}

export interface PolicyOptions {
  /** 개발 서버는 React 가 eval 로 서버 스택을 복원하고 HMR 이 웹소켓을 쓴다. */
  development?: boolean;
}

/**
 * 화면 경로의 정책. 추적이 꺼져 있으면 nonce 와 앱 오리진만 남는다 — 'unsafe-inline' 은
 * 어디에도 넣지 않는다. 한 번 넣으면 추적을 끈 뒤에도 정책은 느슨한 채로 남기 때문이다.
 */
export function buildPagePolicy(config: TrackingConfig, pathname: string, nonce: string, options: PolicyOptions = {}) {
  const scripts = ['\'self\'', `'nonce-${nonce}'`];
  const connects = ['\'self\''];
  const images = ['\'self\'', 'data:', 'blob:'];
  if (options.development) {
    scripts.push('\'unsafe-eval\'');
    connects.push('ws:', 'wss:');
  }

  const active = isTrackingActive(config, pathname);
  if (active) {
    const extra = policySources(config);
    scripts.push(...extra.scripts);
    connects.push(...extra.connects);
    images.push(...extra.images);
  }

  const directives = [
    'default-src \'self\'',
    `script-src ${scripts.join(' ')}`,
    // 화면은 style 속성(React 인라인 스타일)을 쓴다. 스크립트가 아니므로 정책이 막는 대상이 아니다.
    'style-src \'self\' \'unsafe-inline\'',
    `img-src ${images.join(' ')}`,
    'font-src \'self\' data:',
    `connect-src ${connects.join(' ')}`,
    'object-src \'none\'',
    'base-uri \'self\'',
    'form-action \'self\'',
    'frame-ancestors \'self\'',
  ];
  if (active) {
    // 추적이 켜진 동안만 브라우저에게 무엇을 막았는지 알려 달라고 한다.
    directives.push(`report-uri ${CSP_REPORT_PATH}`);
  }
  return directives.join('; ');
}

/** API·프록시 같은 비화면 경로의 정책. 그릴 것이 없으니 전부 막는다. */
export const NON_PAGE_POLICY = 'default-src \'none\'; frame-ancestors \'none\'';

export function extractOrigin(raw: string) {
  return originOf(raw);
}
> `style-src` 에는 `'unsafe-inline'` 이 있습니다. 상황판이 React 인라인 스타일(`style=`)을 쓰기 때문이며, 스타일은 스크립트가 아니므로 위 원칙과 무관합니다.

### 8.2 설정 항목

| 항목 | 뜻 |
|---|---|
| 추적 사용 (`enabled`) | 꺼짐이 기본값입니다. 켜야 스니펫이 붙습니다. |
| 수집 도구 (`provider`) | `momento` · `ga4` · `gtm` · `matomo` · `custom` · `none` |
| `momento_url` · `momento_site_id` | Momento 수집기 주소와 사이트 ID |
| `momento_proxy` | 같은 오리진 프록시(`/momento/*`) 사용 여부. 기본 켜짐 (7.3) |
| `measurement_id` | GA4 측정 ID(`G-…`) 또는 GTM 컨테이너 ID(`GTM-…`) |
| `matomo_url` · `matomo_site_id` | Matomo 주소와 사이트 ID |
| `custom_snippet` | 붙여 넣은 추적 코드. **8KB 제한**, `<script>` 태그만 삽입되며 `<noscript>` 등은 무시됩니다 |
| `allowed_hosts` | 스니펫에서 자동으로 읽지 못한 출처를 손으로 더하는 자리. `https://host[:port]` 또는 `https://*.domain` 모양만 허용되며 쉼표·줄바꿈으로 구분 |
| 관리 화면에서도 추적 (`include_admin`) | 기본 아니오. `/admin` 은 방문자 데이터가 아니므로 켜야만 붙습니다 |
| 삽입 위치 (`placement`) | `head` 또는 `body` 끝 |

저장하면 서버가 값을 검증합니다. 켜져 있을 때 선택한 도구의 필수값이 비어 있거나, 주소가 `http(s)` 로 시작하지 않거나, `allowed_hosts` 모양이 틀리면 `allowed_hosts: "…" 는 https://host[:port] … 모양이어야 합니다` 같은 이유가 화면에 표시되고 저장되지 않습니다. 카드 하단의 **정책에 더해지는 출처** 줄에서 현재 설정으로 정책에 들어가는 외부 출처를 미리 볼 수 있습니다.

같은 설정은 API 로도 다룰 수 있습니다(관리자 세션 필요).

| 메서드 | 경로 | 설명 |
|---|---|---|
| `GET` | `/api/tracking` | 현재 설정, 정책에 더해지는 출처, 삽입될 스크립트 목록 |
| `PUT` | `/api/tracking` | 설정 저장(검증 실패 시 400 과 `details`) |
| `GET` | `/api/tracking/violations` | 정책이 막은 출처 목록 |
| `DELETE` | `/api/tracking/violations` | 목록 비우기 |
| `POST` | `/api/csp-report` | 브라우저의 위반 신고 수신(인증 없음, 추적이 꺼져 있으면 기록하지 않음) |

파일 위치는 `TRACKING_CONFIG_FILE` 환경 변수로 바꿀 수 있고, 지정하지 않으면 `ACTIVITY_DATA_FILE` 과 같은 디렉토리의 `tracking.json` 입니다. Docker 에서는 `/app/data` 볼륨에 함께 보관됩니다.

### 8.3 Momento 연결 (권장)

Momento 는 사내 자체 호스팅 수집기라 데이터가 밖으로 나가지 않는 유일한 선택지이므로 목록의 첫 자리에 있습니다.

1. **추적 사용**을 켜고 수집 도구에서 **Momento** 를 고릅니다.
2. `momento_url` 에 수집기 주소(예: `https://momento.corp.example`), `momento_site_id` 에 이 대시보드의 사이트 ID 를 넣습니다. 환경(`data-environment`)은 기본 `prd` 입니다.
3. **같은 오리진 프록시 사용**은 켜 둡니다(기본). 이 경우 브라우저는 `/momento/tracker.js` 만 부르고, 앱 서버가 `/momento/*` 요청을 수집기로 넘깁니다. 외부 출처가 정책에 아예 등장하지 않으므로 CSP 를 손볼 일이 없고, 방문자 PC 에서 수집기가 직접 닿지 않는 망에서도 동작합니다(앱 서버 → 수집기 경로만 열려 있으면 됩니다).
4. **설정 저장**을 누른 뒤 상황판(`/` 또는 `/pc`)을 한 번 열어 Momento 쪽에 방문이 들어오는지 확인합니다.

삽입되는 태그는 다음과 같습니다(nonce 는 요청마다 다릅니다).

```html
<script async src="/momento/tracker.js" nonce="…"
        data-site-id="<momento_site_id>" data-environment="prd"
        data-contract-version="1" data-endpoint="/momento"></script>
```

프록시를 끄면 `src` 가 `<momento_url>/tracker.js` 가 되고 수집기 출처가 `script-src` · `connect-src` · `img-src` 에 더해집니다.

### 8.4 정책이 막은 출처 확인과 허용

추적이 켜져 있으면 카드 아래에 **정책이 막은 출처** 목록이 나타납니다(5초마다 갱신). 브라우저가 정책 때문에 차단한 요청을 `report-uri` 로 신고하면 앱이 **출처와 지시어**(`script-src`, `connect-src`, `img-src` …)를 기억합니다. 같은 차단이 페이지마다 반복되므로 횟수가 아니라 서로 다른 출처만 최대 100개까지 메모리에 보관하며, 서버를 재시작하면 비워집니다.

- 막힌 출처 옆의 **허용 목록에 추가**를 누르면 `allowed_hosts` 에 들어가 바로 저장되고, 다음 페이지 열람부터 허용됩니다.
- 현재 설정이 이미 허용하는 출처는 **이미 허용됨**으로 표시됩니다.
- 스니펫을 고친 뒤에는 휴지통 아이콘으로 목록을 비우고 상황판을 다시 열어 아직 막히는 것이 있는지 확인합니다.
- 브라우저 확장이나 `data:` URL 처럼 http 출처가 아닌 것은 허용할 수도 없고 쓸모도 없어 기록하지 않습니다.


